begin;

do $$
declare
  native_count integer;
begin
  select count(*)
    into native_count
  from public.calendar_days
  where country_code = 'UA'
    and calendar_code = 'ua-orthodox-church-of-ukraine'
    and language_code = 'uk'
    and calendar_date between date '2026-01-01' and date '2026-12-31';

  if native_count <> 365 then
    raise exception 'Expected 365 native UA rows; found %', native_count;
  end if;
end
$$;

with payload(calendar_date, title) as (
values
(date '2026-01-01','Circumcision of the Lord. Saint Basil the Great, Archbishop of Caesarea in Cappadocia. Venerable Amphilochius of Pochaiv.'),
(date '2026-01-02','Forefeast Holy Theophany. Saint Sylvestra, iepyskopa Rymskoho (335). Venerable Serafyma Sarovskoho, Wonderworker (1833). Venerable Sylvestra Kyievo-of the Caves, in the Near Caves (XII). Hieromartyr Feohena, Bishop Pariiskoho (ca. 320).'),
(date '2026-01-03','Saturday before Holy Theophany. Prophet Malakhii (400 BC). Martyr Hordiia (IV).'),
(date '2026-01-04','30th Sunday after Pentecost, before Holy Theophany. Tone 5. Synaxis of 70-kh apostoliv: Yakova, brother of Hospodnoho; Marka and Luky, Evangelists; Kleopy, Symeona, Varnavy, Iosii, called Yustom, Fadeia, Ananiia, Stefana, Fylypa, Prokhora, Nykanora, Tymona, Parmena, Tymofiia, Tyta, Fylymona, Onysyma, Epafrasa, Arkhypa, Syly, Syluana, Kryskenta, Kryspa, Epeneta, Andronika, Stakhiia, Ampliia, Urvana, Narkysa, Apeliia, Arystovula, Rodiona (Irodiona), Ahava, Rufa, Asynkryta, Flehonta, Yerma, Patrova, Yermiia, Lina, Haia, Filoloha, Lukiia, Yasona, Sosypatra, Olimpa (Olimpana), Tertiia, Erasta, Kuarta, Evoda, Onysyfora, Klymenta, Sosfena, Apollosa, Tykhyka, Epafrodyta, Karpa, Kondrata, Marka, son of Varnavy, Ziny, zakonnyka, Arystarkha, Puda, Trofyma, Marka, Artemy, Akyly, Fortunata, Akhaika, Dionisiia Areopahita and'),
(date '2026-01-05','31th week after Pentecost. Eve of Holy Theophany (Khreshchenskyi Eve). Hieromartyr Feopempta, Bishop Nikomydiiskoho, and mch. Feony, volkhva (303). Venerable Synklitykii Oleksandriiskoi (ca. 350). Prophet Mykheia (IX century BC). Venerable Apolinarii (ca. 470). Venerable Fostyriia and Myny (VI). Venerable Hryhoriia Akrytskoho (ca. 820).'),
(date '2026-01-06','Holy Theophany. Baptism of Our Lord, God and Savior Jesus Christ.'),
(date '2026-01-07','Synaxis of Forerunner and Baptist of the Lord John.'),
(date '2026-01-08','Venerable Heorhiia Khozevita (VII) and Emiliana, Confessor (IX). Venerable Domniky (ca. 474). Venerable Hryhoriia, Wonderworker Kyievo-of the Caves, in the Near Caves (1093). Venerable Hryhoriia, recluse Kyievo-of the Caves, in the Far Caves (XIII – XIV). Hieromartyr Karteriia, presbyter Kesarii Kappadokiiskoi (304). Hieromartyr Feofila, deacon, and mch. Elladiia (IV). Martyr Yuliana, Kelsiia, Anthony, Anastasiia, mtsts. Vasylisy and Marionily, simokh otrokiv and 20-okh voiniv (313). Venerable Illi Yehypetskoho (IV). Martyr Abo Tbiliskoho (ca. 790, Hruz.).'),
(date '2026-01-09','Martyr Poliievkta (259). Prophet Sameia (X century BC). Saint Petra, Bishop Sevastii Virmenskoi (IV). Venerable Yevstratiia, Wonderworker (IX). Venerable Jonah of Kyiv (1902).'),
(date '2026-01-10','Saturday after Holy Theophany. Saint Hryhoriia, Bishop Nyskoho (395). Venerable Dometiana, Bishop Melitynskoho (601). Venerable Markiana, presbyter (V). Venerable Makariia. Blzh. Feozvy, deaconess, sister of svt. Hryhoriia Nyskoho (385).'),
(date '2026-01-11','31th Sunday after Pentecost, after Holy Theophany. Tone 6. Venerable Theodosius the Great, founder of cenobitic monastic life (529). Venerable Theodosius Antiokhiiskoho (ca. 412). Yeletskoi Icon of the Mother of God (1060).'),
(date '2026-01-12','32th week after Pentecost (riadovi chytannia 29-ho tyzhnia because of Khreshchensku vidstupku). Martyr Tetiany and tykh z neiu, iaki in Rymi buly zamucheni (226 – 235). Martyr Mertiia (284 – 305). Martyr Petra Avesalomita (309 – 310). Venerable Yevpraksii, divy Tavenskoi (393). Saint Savy, Archbishop Serbskoho (1237). Icon of the Mother of God, called «Akafistna» and «Molokozhyvytelka».'),
(date '2026-01-13','Martyr Yermyla and Stratonika (ca. 315). Martyr Petra Aniiskoho (309 – 310). Venerable Yakova, Bishop Nyzybiis koho (350).'),
(date '2026-01-14','Leavetaking of the Feast of Holy Theophany. Venerable ottsiv, iaki in Synai and Raifi buly vbyti: Isai, Savy, Moiseia and uchnia his Moiseia, Yeremii, Pavla, Adama, Serhiia, Domna, Prokla, Ipatiia, Isaaka, Makariia, Marka, Veniamina, Yevseviia, Illi and inshykh with nymy (IV – V). Equal-to-the-Apostles Niny, enlightener Hruzii (335). Venerable Yosyfa Analityna Raifskoho (IV). Venerable Feodula (V). Venerable Stefana (VIII).'),
(date '2026-01-15','Venerable Pavla Fiveiskoho (341) and John Kushchnyka (V). Venerable Martyr Pansofiia (249 – 251). Venerable Prokhora (X) and Havryila (XI, Serb.).'),
(date '2026-01-16','Pokloninnia okovam ap. Petra. Martyr Spevsypa, Yelevsypa, Malevsypa and babtsi their Leonily, and z nymy Neona, Turvona and Iovyly (161 – 180). Martyr Danakta, chyttsia (II).'),
(date '2026-01-17','Venerable Anthony the Great (356).'),
(date '2026-01-18','32th Sunday after Pentecost. Tone 7. Saint Afanasiia (373) and Kyryla (444), Archbishops Oleksandriiskykh. Venerable Markiana Kyrskoho (ca. 388).'),
(date '2026-01-19','33th week after Pentecost (riadovi chytannia 32-ho tyzhnia because of Khreshchensku vidstupku). Venerable Makariia the Great, Yehypetskoho (390 – 391). Saint Marka, Archbishop Efeskoho (1457). Venerable Makariia, faster Kyievo-of the Caves, in the Near Caves (XII). Venerable Makariia, deacon Kyievo-of the Caves, in the Far Caves (XIV). Martyr Yevfrasii, divy (303). Venerable Makariia Oleksandriiskoho (394 – 395). Saint Arseniia, Archbishop Kerkyrskoho (VIII). Venerable Anthony, stylite, Martkobskoho (VI, Hruz.). Venerable Lavrentiia Chernihivskoho (1950).'),
(date '2026-01-20','Venerable Yevfymiia the Great (473). Martyr Inny, Pinny and Rymmy (I – II). Venerable Yevfymiia skhymnyka (XIV) and Lavrentiia recluse (XIII – XIV), of the Kyiv Caves, in the Far Caves. Martyr Vassa, Yevseviia, Yevtykhiia and Vasylida (303).'),
(date '2026-01-21','Venerable Maksyma Spovidnyka (662). Martyr Neofita (304). Martyr Yevheniia, Kandyda, Valeriana and Akyly (III). Venerable Maksyma Hreka (1556). Martyr Ahnii, divy (ca. 304). Martyr Anastasiia (662). Ktytorskoi (IV) and nazvanoi «Vidrada» abo «Vtikha» (807), Vatopedskykh Icon of the Mother of God.'),
(date '2026-01-22','Apostle Tymofiia (ca. 96). Venerable Martyr Anastasiia Perskoho (628). Venerable Martyr Anastasiia, dyiak. Kyievo-of the Caves, in the Near Caves (XII). Hieromartyr Manuila, Heorhiia, Petra, Leontiia, iepyskopiv, Syoniia, Havryila, John, Leonta, Paroda, presviteriv, and inshykh 377 Martyrs (ca. 817).'),
(date '2026-01-23','Hieromartyr Klymenta, Bishop Ankyrskoho, and mch. Ahafanhela (312). Venerable Mavsymy Syriitsia (IV). Venerable Samana, movchalnyka (ca. 400). Saint Pavlina Mylostyvoho, Bishop Nolanskoho (431). Pam’iat VI Vselenskoho Synaxis ofu (680 – 681).'),
(date '2026-01-24','Venerable Ksenii Rymlianky, dyiakonisy (V). Martyr Vavyly Sytsyliiskoho and uchniv his Tymofiia and Ahapiia (III). Venerable Makedoniia, syriiskoho pustelnyka (ca. 420).'),
(date '2026-01-25','33th Sunday after Pentecost. Tone 8. Saint Hryhoriia Bohoslova, Archbishop Konstantynopolskoho (389). Martyr Filitsaty and syniv her mchch. Yanuariia, Feliksa, Fylypa, Sylvana, Oleksandra, Vitaliia and Martsiala (164). Venerable Popliia Syriiskoho (380). Venerable Mara, spivtsia (ca. 430). Icon of the Mother of God, zvanoi «Utamui moi pechali».'),
(date '2026-01-26','34th week after Pentecost. Venerable Ksenofonta, druzhyny his Marii and syniv ikhnikh Arkadiia and John (V – VI). Martyr Ananii, presbyter, Petra, storozha in’iaznytsi, a z nymy simokh voiniv (295). Venerable Symeona Drevnoho, pustelnyka (ca. 390). Perenesennia moshchiv prp. Fedora, ihumena Studiiskoho (845). Saint Yosyfa, Archbishop Solunskoho (830). Right-believing Davyda III Vidnovytelia, tsaria Iverii and Abkhazii (1 125, Hruz.).'),
(date '2026-01-27','Perenesennia moshchiv svt. John Zolotoustoho (438).'),
(date '2026-01-28','Venerable Yefrema Syrina (373 – 379). Venerable Yefrema Kyievo-of the Caves, Bishop Pereiaslavskoho (ca. 1098). Venerable Palladiia, pustelnyka (IV). Venerable Isaaka Syrina, Bishop Nineviiskoho (VI). Venerable Yefrema Uhryna, Novotorzkoho (1053). Saint iepp. Pereiaslavskykh: Yefrema († ca. 1098), Nicholas († 1074), Petra († 1082), Lazaria († 1 1 1 7), Sylvestra († 1 123), Yevfymiia († 1 155), Symeona († 1239).'),
(date '2026-01-29','Perenesennia moshchiv sshchmch. Ihnatiia Bohonostsia (107). Saint Lavrentiia, recluse Kyievo-of the Caves, Bishop Turivskoho, in the Near Caves (1 194). Martyr Romana, Yakova, Filofeia, Iperykhiia, Aviva, Yuliana and Paryhoriia (297). Hieromartyr Sylvana, Bishop, Luky, dyiak., mch. Mokiia, chyttsia (312).'),
(date '2026-01-30','Synaxis of vselenskykh uchyteliv and sviatyteliv Basil the Great, Hryhoriia Bohoslova and John Zolotoustoho. Hieromartyr Ipolyta, Bishop Rymskoho and z nym mchch. Kensoryna, Savyna, Frysii, divy and inshykh 20 mchch. (III). Venerable Zynona, faster Kyievo-of the Caves, in the Far Caves (XIV). Venerable Zynona, uchnia svt. Basil the Great (V). Martyr Feofila Novoho (784). Right-believing Petra, tsaria Bolharskoho (967).'),
(date '2026-01-31','Bezsrr., mchch. Kyra and John and z nymy mtsts. Afanasii and dochok her Feodotii, Feoktysty and Yevdoksii (31 1). Saint Mykyty, recluse Kyievo-of the Caves, Bishop Novhorodskoho (1 108). Martyr Viktoryna, Viktora, Nykyfora, Klavdiia, Diodora, Serapiona and Papiia (251). Martyr Tryfeny Kyzytskoi.'),
(date '2026-02-01','Sunday pro mytaria and faryseia. Tone 1. Forefeast Stritennia of the Lord. Martyr Tryfona (250). Martyr Perpetui and Felitsytaty, mchch. Satyra, Revokata, Satornyla, Sekunda (202 – 203). Venerable Petra Halatiiskoho (429). Venerable Vendymiana, pustelnyka Vyfyniiskoho (ca. 512).'),
(date '2026-02-02','Meeting of Our Lord Jesus Christ in the Temple.'),
(date '2026-02-03','Afterfeast Stritennia of the Lord. Afterfeast Stritennia Hospodnoho. Pravv. Symeona Bohopryimtsia and Anny, prorochytsi (I). Prophet Azarii (X century BC). Martyr Papiia, Diodora, Klavdiana (250). Martyr Adriana and Yevvula (308 – 309). Martyr Vlasiia Kesariiskoho (III). Saint Ihnatiia Mariupolskoho, Metropolitan Hotfeiskoho and Kefaiskoho (1 786). Equal-to-the-Apostles Nicholas, Archbishop Yaponskoho (1912). Znaidennia moshchiv svt. Rafaila (Zaborovskoho), Metropolitan of Kyiv, Halytskoho and vsiiei Rusy (2024). Den intronizatsii Blazhenniishoho Mytropolyta of Kyiv and vsiiei Ukrainy Epifaniia.'),
(date '2026-02-04','Venerable Isydora Pelusiota (ca. 436 – 440). Martyr Iadora (III). Hieromartyr Avraamiia, Bishop Arvilskoho (ca. 344 – 347). Venerable Nicholas, Confessor, ihumena Studiiskoho (868).'),
(date '2026-02-05','Martyr Ahafii (251). Saint Theodosius, Archbishop Chernihivskoho (1 696). Martyr Feoduly and mchch. Elladiia, Makariia and Yevahriia (ca. 304). Yeletsko-Chernihivskoi (1060), Sytsyliiskoi, abo Dyvnohorskoi (1092), and zvanoi «Vidnaidennia za hyblykh» Icon of the Mother of God.'),
(date '2026-02-06','Venerable Vukola, Bishop Smyrnskoho (ca. 100). Venerable Varsonofiia the Great and John, proroka (VI). Saint Fotiia, patr. Konstantynopolskoho (891). Martyr Dorofei, Khrystyny, Kallisty and mch. Feofila (288 – 300). Martyr Favsty, mchch. Yevilasiia and Maksyma (305 – 31 1). Martyr Yuliana (312). Martyr Marfy, Marii and brother of ikh prmch. Lykariona, iunaka.'),
(date '2026-02-07','Venerable Parfeniia, Bishop Lampsakiiskoho (IV). Venerable Luky Elladskoho (ca. 946). 1003 mchch. Nikomydiiskykh (303).'),
(date '2026-02-08','Sunday pro bludnoho son of. Hlas 2. Great Martyr Fedora Stratylata (319). Prophet Zakharii Serpovydtsia (ca. 520 do R. X.). Saint Savy II, Archbishop Serbskoho (1268 – 1269).'),
(date '2026-02-09','Leavetaking of the Feast of Stritennia of the Lord. Martyr Nykyfora z Antiokhii Syriiskoi (ca. 257). Venerable Pankratiia, iierom., recluse Kyievo-of the Caves, in the Far Caves (XIII). Znaidennia moshchiv svt. Inokentiia (Kulchytskoho), Bishop Irkutskoho (1805). Hieromartyr Markela, Bishop Sykeliiskoho, Filahriia, Bishop Kiprskoho, and Pankratiia, Bishop Tavromeniiskoho (I).'),
(date '2026-02-10','Hieromartyr Kharalampiia and z nym mchch. Porfyriia and Vaptosa and trokh muchenyts (202). Venerable Prokhora, Wonderworker Kyievo-of the Caves, in the Near Caves (1 107). Martyr div Yenafy, Valentyny and Pavly (308). Right-believing kn. Anny Novhorodskoi (1056). Icon of the Mother of God «Vohnevydna».'),
(date '2026-02-11','Hieromartyr Vlasiia, Bishop Sevastiiskoho (ca. 316). Right-believing kn. Vsevoloda, u khreshchenni Havryila, Pskovs koho (1 138). Righteous Feodory, tsarytsi Hretskoi, shcho vidnovyla vshanuvannia Saints Icon (ca. 867).'),
(date '2026-02-12','Iverskoi Icon of the Mother of God. Saint Meletiia, Archbishop Antiokhiiskoho (381). Saint Oleksiia, Metropolitan of Kyiv and vsiiei Rusy, Wonderworker (1378). Saint Meletiia, Archbishop Kharkivskoho (1840). Venerable Marii, zvanoi Marynom, and batka her Yevheniia (VI). Saint Anthony, patr. Konstantynopolskoho (895).'),
(date '2026-02-13','Venerable Martyniana (V). Venerable Zoi and Fotynii (Svitlany) (V). Venerable Yevlohiia, Archbishop Oleksandriiskoho (607 – 608). Right-believing kn. Kostiantyna Ostrozkoho (1 608). Venerable Stefana, u chernetstvi Symeona, tsaria Serbskoho, Myrotochyvoho (1200).'),
(date '2026-02-14','Saturday m’iasopusna. Pam’iat usikh vid viku spochylykh pravoslavnykh khrystyian – ottsiv, brativ and sester nashykh. Venerable Avksentiia (ca. 470). Equal-to-the-Apostles Kyryla, uchytelia slov’ianskoho (869). Venerable Isakiia, recluse Kyievo- of the Caves, in the Near Caves (ca. 1090). 12-okh hrekiv, budivnykiv Synaxis ofnoi Uspenskoi tserkvy Kyievo-Pecherskoi lavry (XI). Venerable Marona, pustelnyka Syriiskoho (IV). Saint Avraamiia, Bishop Karriiskoho (V).'),
(date '2026-02-15','Sunday m’iasopusna, pro Strashnyi sud. Tone 3. Apostle vid 70-kh Onysyma (ca. 109). Venerable Pafnutiia, recluse Kyievo-of the Caves, in the Far Caves (XIII). Venerable Pafnutiia and dochky his Yefrosynii (V). Venerable Yevseviia, pustelnyka Syriiskoho (V). Vilenskoi (perenesennia u Vilno in 1495 r.) and Dalmatskoi (1646) Icon of the Mother of God.'),
(date '2026-02-16','week syrnyi (maslianyi) – zahalnytsia. Hieromartyr Pamfila, presbyter, Valenta (Ualenta), deacon, mchch. Pavla, Porfyriia, Selevkiia, Feodula, Yuliana, Samuila, Illi, Danyila, Yeremii, Isai (307 – 309). Martyr perskykh in Martyropoli (IV). Venerable Marufa, Bishop Mesopotamskoho (422).'),
(date '2026-02-17','Great Martyr Fedora Tyrona (ca. 306). Venerable Fedora, movchalnyka Kyievo-of the Caves, in the Far Caves (XIII). Righteous Mariamny, sister of ap. Fylypa (I). Znaidennia moshchiv mch. Myny Kalikelada (867 – 889).'),
(date '2026-02-18','Saint Leva, papy Rymskoho (461). Saint Ahapita, Confessor, Bishop Synadskoho (IV). Saint Flaviana, Confessor, patr. Konstantynopolskoho (449 – 450). Venerable Kosmy Yakhromskoho (1492).'),
(date '2026-02-19','Apostle vid 70-kh: Arkhypa and Fylymona and mts. rivnoap. Apfii (I). Martyr Maksyma, Feodota, Isykhiia, mts. Asklypiodoty (305 – 31 1). Venerable Yevheniia and Makariia, spovidnykiv, presviteriv Antiokhiiskykh (363). Venerable Dosyfeia (VII), uchnia prp. avvy Dorofeia. Venerable Ravuly (ca. 530). Venerable Shio Mhvymskoho (VI, Hruz.) (perekhidne sviatkuvannia u chetver syropusnoho tyzhnia).'),
(date '2026-02-20','Venerable Leva, Bishop Katanskoho (ca. 780). Right-believing kn. of Kyiv Yaroslava Mudroho (1054). Venerable Ahafona, Wonderworker Kyievo-of the Caves, in the Far Caves (XIII – XIV). Hieromartyr Sadoka, Bishop Perskoho, and z nym 128 mchch. (342 – 344). Venerable Ahafona, papy Rymskoho (682). TsOHO DNYa BOZhESTVENNA LITURHIYa NE ZVERShUYeTSYa.'),
(date '2026-02-21','Vsikh prepodobnykh ottsiv, shcho in podvyhu prosiaialy (perekhidne sviatkuvannia in subotu syropusnoho tyzhnia). Venerable Tymofiia, shcho in Symvolakh (795). Saint Yevstafiia, Archbishop Antiokhiiskoho (337). Saint Heorhiia, Bishop Amastrydskoho (802 – 81 1). Kozelshchanskoi Icon of the Mother of God (1881).'),
(date '2026-02-22','Sunday syropusna, proshchena. Spomyn Adamovoho vyhnannia z raiu. Tone 4. Martyr Mavrykiia and 70-okh voiniv: Fotyna, Fedora, Fylypa and inshykh (ca. 305). Znaidennia moshchiv Martyrs, shcho in Yevhenii (395 – 423). Venerable Falasiia, Lymniia and Varadata, pustelnykiv syriiskykh (V). Venerable Afanasiia, Confessor (821).'),
(date '2026-02-23','1th week Great Lent. Hieromartyr Polikarpa, Bishop Smyrnskoho (167). Venerable John, Antiokha, Antonina, Moiseia, Zevyna, Polikhroniia, inshoho Moiseia and Damiana, pustelnykiv syriiskykh (V). Venerable Oleksandra, founder of obyteli «Nevsypushchykh» (ca. 430).'),
(date '2026-02-24','Pershe (IV) and druhe (452) znaidennia holovy John Forerunner. Venerable Erazma Kyievo-of the Caves, in the Near Caves (ca. 1 1 60).'),
(date '2026-02-25','Saint Tarasiia, Archbishop Konstantynopolskoho (806).'),
(date '2026-02-26','Saint Porfyriia, Archbishop Hazkoho (420). Martyr Sevastiana (ca. 66).'),
(date '2026-02-27','Venerable Prokopiia Dekapolita, Confessor (ca. 750). Venerable Tyta, presbyter Kyievo-of the Caves, in the Near Caves (1 190). Venerable Tyta Kyievo-of the Caves, kolyshnoho voina, shcho in the Far Caves (XIV ). Venerable Falaleia Syriiskoho (ca. 460). Venerable Yefrema Katunakskoho (1998).'),
(date '2026-02-28','Great Martyr Fedora Tyrona (ca. 306) (perekhidne sviatkuvannia in subotu 1-ho tyzhnia Great Lent). Saint Arseniia (Matsiievycha), Metropolitan Rostovskoho (1 772 ). Venerable Vasyliia, Confessor (750). Hieromartyr Proteriia, patr. Oleksandriiskoho (457). Hieromartyr Nestora, Bishop Mahidiiskoho (250). Venerable Maryny and Kiry (ca. 450). Venerable Kasiia -'),
(date '2026-03-01','1th Sunday Great Lent. Torzhestvo Pravoslav’ia. Tone 5. Prmts. Yevdokii (ca. 160 – 170). Martyr Nestora and Tryvimiia (III). Martyr Antoniny (III – IV). Martyr Markela and Anthony. Venerable Domniny Syriiskoi (ca. 450 – 460).'),
(date '2026-03-02','2th week Great Lent. Hieromartyr Feodota, Bishop Kyryneiskoho (ca. 326). Saint Iova (Boretskoho), Metropolitan of Kyiv and vsiiei Rusy (1 631) (sluzhbu sviatyteliu dyvys 15 bereznia). Martyr Yevfalii (257). Martyr Troadiia (III). Venerable Ahafona Yehypetskoho (V). Martyr 440 italiiskykh (579). Saint Arseniia, Bishop Tverskoho (1409).'),
(date '2026-03-03','Martyr Yevtropiia, Kleonyka and Vasyliska (ca. 308). Venerable Piamy, divy (337). Saint Zynona and Zoila.'),
(date '2026-03-04','Venerable Herasyma, shcho na Yordani (475). Martyr Pavla and mts. Yulianii (ca. 273). Venerable Yakova, faster (VI). Perenesennia moshchiv blhv. kn. V’iacheslava Cheskoho (938). Venerable Herasyma of Kyiv, Abbot Volohodskoho (1 1 78). Saint Hryhoriia, Bishop Konstantsii Kiprskoi. Venerable Martyr Ioasafa Snitnohorskoho (1299).'),
(date '2026-03-05','Martyr Konona Isavriiskoho (I). Martyr Onysiia (I). Martyr Konona, hradaria (zemleroba) (III). Venerable Marka (V). Venerable Isykhiia (ca. 790). Martyr Iraidy. Martyr Yevlohiia, shcho in Palestyni. Martyr Yevlampiia.'),
(date '2026-03-06','Martyr 42 in Ammorii: Kostiantyna, Aetiia, Feofila, Fedora, Melisena, Kalista, Vasoia and inshykh z nymy (ca. 845). Znaidennia chesnoho Khresta and tsviakhiv sv. tsarytseiu Olenoiu in Yerusalymi (326). Venerable Martyr Konona and son of his Konona (270 – 275). Venerable Arkadiia Kiprskoho (ca. 361). Icon of the Mother of God Chenstokhovskoi, Shestokivskoi and «Blahodatne nebo».'),
(date '2026-03-07','SviashchennoMartyrs, iaki in Khersonesi buly iepyskopamy: Vasyliia, Yefrema, Kapitona, Yevheniia, Yeferiia, Elpidiia and Ahafodora (IV ). Venerable Pavla Preprostoho (IV). Saint Pavla, Confessor, Bishop Prusiadskoho (IX). Venerable Emiliana Italiiskoho. Icon of the Mother of God «Sporuchnytsia hrishnykh». Pomynannia pomerlykh.'),
(date '2026-03-08','Sunday 2-ha Great Lent. Hlas 6-yi. Saint Hryhoriia Palamy, Archbishop Fesalonikiiskoho (perekhidne sviatkuvannia in 2-hu nediliu Great Lent). Synaxis of usikh prepodobnykh ottsiv of the Kyiv Caves (perekhidne sviatkuvannia in 2-hu nediliu Great Lent). BEREZEN BohosluzhBovi vkazivky 2026 76 Venerable Feofilakta, Confessor, Bishop Nikomydiiskoho (842 – 845). Apostle Yerma (I). Hieromartyr Feodoryta, presbyter Antiokhiiskoho (361 – 363). Venerable Dometiia (363).'),
(date '2026-03-09','3th week Great Lent. 40 mchch., shcho in Sevastiiskomu ozeri muchylysia: Kiriona, Kandyda, Domna, Isykhiia, Irakliia, Smarahda, Yevnoika, Valenta, Vyviana, Klavdiia, Priska, Feodula, Yevtykhiia, John, Ksanfiia, Iliana, Sysyniia, Anhiia, Aetiia, Flaviia, Akakiia, Ekdykiia (Ekdyta), Lisymakha, Oleksandra, Iliia, Horhoniia, Feofila, Dometiana, Haia, Leontiia, Afanasiia, Kyryla, Sakerdona, Nicholas, Valeriia, Filoktymona, Severiana, Khudiona, Melitona and Ahlaiia (ca. 320). Martyr Urpasiana (ca. 295). Saint Kesariia, brother of svt. Hryhoriia Bohoslova (ca. 369). Righteous Tarasiia Likaoniiskoho.'),
(date '2026-03-10','Martyr Kodrata and z nym Kypriana, Dionisiia, Anekta, Pavla, Kryskenta, Dionisiia (inshoho), Viktoryna, Viktora, Nykyfora, Klavdiia, Diodora, Serafiona, Papiia, Leonida and mtsts. Khariiesy, Nunekhii, Vasylisy, Niky, Hali, Halyny, Feodory and inshykh bahatokh (ca. 258). Martyr Kodrata Nikomydiiskoho, Satoryna, Rufyna and inshykh (III). Venerable Anastasii (567 – 568).'),
(date '2026-03-11','Saint Sofroniia, patr. Yerusalymskoho (639). Venerable Sofroniia, recluse Kyievo-of the Caves, in the Far Caves (XIII). Hieromartyr Pioniia, presbyter Smyrnskoho, and inshykh z nym (250). Perenesennia moshchiv mch. Epymakha. Saint Sofroniia, Bishop Vrachanskoho (1813, Bolh.).'),
(date '2026-03-12','Venerable Feofana, Confessor, Syhrianskoho (818). Righteous Fineiesa (ca. 1500 BC). Saint Hryhoriia Dvoieslova, papy Rymskoho (604). Venerable Symeona Novoho Bohoslova (1021). Liddskoi [nerukotvornoi] (in Liddi na stovpi) Icon of the Mother of God (I).'),
(date '2026-03-13','Perenesennia moshchiv svt. Nykyfora, patr. Konstantynopolskoho (846). Martyr Savyna (287). Martyr Afrykana, Publiia and Terentiia (III). Martyr Oleksandra (305 – 31 1). Martyr Khrystyny Perskoi (IV). Venerable Anina Khalkidonskoho, presbyter.'),
(date '2026-03-14','Venerable Venedykta (543). Saint Feohnosta, Metropolitan of Kyiv and vsiiei Rusy (1353). Right-believing vel. kn. of Kyiv Rostyslava, u khreshchenni Mykhaila (1 1 67). Saint Yevskhymona, Confessor, Bishop Lampsakiiskoho (IX). Icon of the Mother of God «Sporuchnytsia hrishnykh». Pomynannia pomerlykh.'),
(date '2026-03-15','Sunday 3-tia Great Lent, khrestopoklonna. Hlas 7-yi. Martyr Ahapiia and z nym semy mchch.: Publiia, Tymolaia, Romyla, dvokh Oleksandriv and dvokh Dionisiiv (303). Hieromartyr Oleksandra, presbyter in Sydi (270 – 275). Martyr Nykandra (ca. 302).'),
(date '2026-03-16','4th week Great Lent. Apostle Arystovula, Bishop Vrytaniiskoho (Brytanskoho, I). Martyr Savyna (287). Martyr Papy (305 – 31 1). Hieromartyr Oleksandra, iepyskopa Rymskoho (1 19). Martyr Yuliana Anazavrskoho (305 – 31 1). Hieromartyr Trofyma and Fala, presviteriv Laodykiiskykh (ca.300).'),
(date '2026-03-17','Venerable Oleksiia, liudyny Bozhoi (4 1 1). Saint Patrykiia, enlightener Irlandii (after 460). Martyr Maryna.'),
(date '2026-03-18','Saint Kyryla, Archbishop Yerusalymskoho (386). Martyr Trofyma and Yevkarpiia (ca. 300). Venerable Anina, chentsia.'),
(date '2026-03-19','Martyr Khrysanfa and mts. Darii (283) and z nymy mchch. Klavdiia, trybuna, Ilarii, druzhyny his, Yasona and Mavra, syniv ikhnikh, sshchmchch. Diodora, presbyter, and Mar’iana, deacon. Martyr Pankhariia (ca. 302).'),
(date '2026-03-20','Venerable Martyr John, Serhiia, Patrykiia and inshykh, iaki in obyteli sv. Savy buly vbyti (796). Martyr Fotyny (Svitlany), samarianky, her syniv mchch. Viktora, nazvanoho Fotynom, and Iosii (I). Martyr Anatolii, Foto, Fotydy, Paraskevy, Kyriakii, Domniny and mch. Sevastiana (ca. 66). Martyr Oleksandry, Klavdii, Yevfrasii, Motrony, Yulianii, Yevfymii and Feodosii (310). Saint Mykyty, Confessor, Archbishop Apoloniadskoho (ca. 813 – 820).'),
(date '2026-03-21','Venerable Yakova, Bishop Katanskoho, Confessor (VIII). Saint Kyryla, Bishop Katanskoho (I – II). Saint Fomy, patr. Konstantynopolskoho (610). Pomynannia pomerlykh.'),
(date '2026-03-22','Sunday 4-and Great Lent. Hlas 8. Venerable John Listvychnyka (perekhidne sviatkuvannia in 4-tu nediliu Great Lent). Hieromartyr Vasyliia, presbyter Ankyrskoho (362 – 363). Martyr Drosydy, dochky tsaria Traiana (104 – 1 17). Venerable Isaakiia Dalmatskoho (IV).'),
(date '2026-03-23','5th week Great Lent. Venerable Martyr Nykona Sytsyliiskoho, Bishop, and mchch. 199 uchniv his (251). Venerable Nykona, ihumena Kyievo-of the Caves (1088). Martyr Filyta, Lidii, druzhyny his, Makedona, Feoprepiia, Kronida and Amphilochius (1 17 – 138).'),
(date '2026-03-24','Forefeast Blahovishchennia the Most Holy Theotokos. Venerable Zakharii, chentsia. Saint Artemiia (Artemona), Bishop Solunskoho (Selevkiiskoho, I – II). Venerable Zakharii, faster Kyievo-of the Caves, in the Far Caves (XIII – XIV). Venerable Yakova, Bishop Katanskoho, Confessor (VIII – IX).'),
(date '2026-03-25','Annunciation of Our Most Holy Lady Theotokos and Ever-Virgin Mary.'),
(date '2026-03-26','Chetver velykoho kanonu. Leavetaking of the Feast of Blahovishchennia the Most Holy Theotokos. Synaxis of arkhanhela Havryila. Hieromartyr Iryneia, Bishop Syriiskoho (304). Martyr Vafusiia and Verka, presviteriv, Arpyly, chentsia, myrian Aviva, Ahna, Reasa, Ihafraksa, Iskoia, Syly, Syhytsia, Sonyryla, Suymvla, Ferma, Fyla and mtsts. Anny, Ally, Larysy, Moiko, Mamiky, Uirko, Animaisy (Animaidy), Haafy, tsarytsi Hotskoi, and Duklidy (ca. 375). Venerable Malkha Syriiskoho (IV). Venerable Vasyliia Novoho (ca. 944).'),
(date '2026-03-27','Martyr Motrony Solunskoi (III – IV). Martyr Manuila and Theodosius (304). Venerable John, prozorlyvoho, Yehypetskoho (ca. 395).'),
(date '2026-03-28','Pokhvala the Most Holy Theotokos (Saturday akafistna). Venerable Ilariona Novoho, Abbot Pelikitskoho (ca. 754). Venerable Stefana Wonderworker, Confessor, Abbot Tryhliiskoho (ca. 815). Martyr Jonah, Varakhysiia and in. z nymy (ca. 330). Martyr Boiana, kn. Bolharskoho (830). Venerable Martyr Yevstratiia Kyievo-of the Caves, in the Near Caves (1097).'),
(date '2026-03-29','5th Sunday Great Lent. Tone 1. Venerable Marii Yehypetskoi ( perekhidne sviatkuvannia in 5-tu nediliu Great Lent ). Hieromartyr Marka, Bishop Arefusiiskoho, Kyryla, deacon, and inshykh bahatokh (ca. 364). Venerable John, pustelnyka (IV). Saint Yevstafiia, Confessor, Bishop Vyfyniiskoho (IX).'),
(date '2026-03-30','6th week Great Lent (verbnyi week). Venerable John Listvychnyka (649). Prophet Ioada (X century BC). Apostle Sosfena, Apolosa, Kyfy, Kesaria and Epafrodyta. Saint Yevuly, materi vmch. Panteleimona (ca. 303). Venerable John, bezmovnyka (VI). Venerable Zosymy, Bishop Syrakuzkoho (ca. 662). Saint Sofroniia (Kryshtalevskoho), Bishop Irkutskoho (1 771).'),
(date '2026-03-31','Hieromartyr Ipatiia, Bishop Hanhrskoho (ca. 326). Venerable Ipatiia, tsilytelia Kyievo-of the Caves, in the Far Caves (XIV). Venerable Apoloniia Yehypetskoho (IV). Hieromartyr Avdy, Bishop Perskoho, and Veniamina, deacon (418 – 424). Venerable Ipatiia, ihumena in Rufiianakh (ca. 446). Prmts. Marii Paryzkoi (1945).'),
(date '2026-04-01','Venerable Marii Yehypetskoi (522). Venerable Herontiia, kanonarkha Kyievo-of the Caves, in the Far Caves (XIV). Venerable Makariia, ihumena Pelikytskoi obyteli (ca. 830). Martyr Herontiia and Vasylida (III). Righteous Akhaza.'),
(date '2026-04-02','Venerable Tyta, Wonderworker (IX). Martyr Amfiana and Edesiia (306). Martyr Polikarpa Oleksandriiskoho (IV).'),
(date '2026-04-03','Venerable Mykyty, spovidnyka, Abbot obyteli Mydykiiskoi (824). Martyr Feodosii, divy (307 – 308). Venerable Iliryka. Martyr Elpidofora, Diia, Vifoniia and Halyka. Icon of the Mother of God «Nev’ianuchyi tsvit».'),
(date '2026-04-04','Lazareva Saturday. Voskreshennia prav. Lazaria. Venerable Yosyfa Pisnepystsia (883). Venerable Heorhiia, shcho in Malei (IX). Venerable Yosyfa Bahatokhvoroblyvoho, Kyievo-of the Caves, in the Far Caves (XIV). Venerable Zosymy (ca. 560). Martyr Fervufy, divy, sister of and rabyni her (341 – 343). Icon of the Mother of God, zvanoi «Herondysa».'),
(date '2026-04-05','Sixth Sunday of Great Lent, Palm Sunday. Entry of the Lord into Jerusalem.'),
(date '2026-04-06','Strasnyi week. Velykyi ponedilok. Saint Yevtykhiia, Archbishop Konstantynopolskoho (582). Saint Mefodiia, Archbishop Moravs- koho (885). Venerable Platonidy (308). Martyr 120 perskykh (344 – 347). Martyr Yeremiia and sshchmch. Arkhyliia, presbyter (III).'),
(date '2026-04-07','Velykyi vivtorok. Venerable Heorhiia, spovidnyka, Metropolitan Mitylenskoho (after 820). Martyr Kaliopiia (304). Hieromartyr Rufyna, deacon, mts. Akylyny and z nymy 200 voiniv (ca. 310). Venerable Serapiona, chentsia. Venerable Yustyna (Popovycha), Cheliiskoho (1978, Serb.). Sluzhba zvershuietsia za zrazkom bohosluzhinnia u Velykyi ponedilok.'),
(date '2026-04-08','Velyka sereda. Apostle Irodiona, Ahava, Asynkryta, Rufa, Flehonta, Yerma and inshykh z nymy (I). Venerable Rufa, recluse Kyievo-of the Caves, in the Far Caves (XIV). Martyr Pavsylypa (1 17 – 138). Saint Tselestyna, papy Rymskoho (432). Saint Nyfonta Kyievo-of the Caves, Bishop Novhorodskoho (1 156). Sluzhba zvershuietsia za zrazkom bohosluzhinnia u Velykyi ponedilok.'),
(date '2026-04-09','Velykyi chetver. Spomyn Taiemnoi vecheri. Martyr Yevpsykhiia (362). Hieromartyr Disana, Bishop, Mariava, presvit., mchch. Avdiiesa and in. 270-kh (362 – 364). Venerable Martyr Vadyma, arkhim. (376).'),
(date '2026-04-10','Velyka p’iatnytsia. Spomyn Saints spasytelnykh strastei Lord nashoho Isusa Khrysta. Martyr Terentiia, Pompiia, Afrykana, Maksyma, Zynona, Oleksandra, Fedora and inshykh 33 (ca. 249 – 251). Hieromartyr Yakova, presbyter, Azadana and Avdykiia, dyiakoniv Perskykh (ca. 380). Right-believing hetmana Petra (Konashevycha-Sahaidachnoho) (1 622). Venerable Martyr sviashchennoi obyteli Pantokratora, iaki in Dau Pendeli (Attyka) postrazhdaly (ca. 1680). Hieromartyr Hryhoriia V, patr. Konstantynopolskoho (1821).'),
(date '2026-04-11','Velyka Saturday. Hieromartyr Antypy, Bishop Perhama Asiiskoho (ca. 68). Martyr Prokesa and Martyniana (ca. 67). Venerable Farmufiia (IV). Venerable John, uchnia prp. Hryhoriia Dekapolita (820 – 850). Saint Kalynyka Chernykskoho (1868, Rum.).'),
(date '2026-04-12','Bright Resurrection of Christ. Pascha.'),
(date '2026-04-13','Paskhalnyi week. Zahalnytsia. Svitlyi ponedilok. Hieromartyr Artemona, presbyter Laodykiiskoho (303). Martyr Kryskenta z Myr Likiiskykh. Martyr Fomaidy Yehypetskoi (476).'),
(date '2026-04-14','Svitlyi vivtorok. Iverskoi Icon of the Mother of God (perekhidne sviatkuvannia u vivtorok Svitloho tyzhnia). Saint Martyna, Confessor, papy Rymskoho (655). Martyr Anthony, John and Yevstafiia Lytovskykh (1347). Martyr Ardaliona (305 – 31 1). Martyr 1000 perskykh and Azata, skoptsia (ca. 341). Martyr Khrystodula and Anastasii Patrskykh, vbytykh in Akhai (1821). Venerable Martyr ottsiv Davydo-Haredzhyiskykh (KhVII, Hruz.) (perekhidne sviatkuvannia u vivtorok Svitloho tyzhnia).'),
(date '2026-04-15','Svitla sereda. Vyshhorodskoi (Volodymyrskoi) Icon of the Mother of God (I). Apostle vid 70-kh Arystarkha, Puda and Trofyma (ca. 67). Martyr Vasylisy and Anastasii (ca. 68). Martyr Mesukeviiskykh Sukhiia and voiniv his: Andriia, Anastasiia, Talale, Feodoryta, Ivkhyriona, Yordana, Kindrata, Lukiana, Mymnenosa, Neranhiosa, Poliievkta, Yakova, Foky, Domentiana, Viktora, Zosymy (100 – 130, Hruz.). Martyr Savy Hotskoho (372). Right-believing kn. Mstyslava Volodymyrovycha (1 132). Synaxis of prepodobnykh ottsiv, iaki na hori Synai podvyzalysia (perekhidne sviatkuvannia in seredu Svitloho tyzhnia). Vilenskoi Icon of the Mother of God. Kasperivskoi Icon of the Mother of God (perekhidne sviatkuvannia in seredu Svitloho tyzhnia).'),
(date '2026-04-16','Svitlyi chetver. Martyr Ahafii, Iryny and Khionii (304). Martyr Leonida and mtsts. Khariiesy, Niky, Halyny, Kalisy, Nunekhii, Vasylisy, Feodory, Iryny and inshykh (258). Illinsko-Chernihivskoi Icon of the Mother of God (1 658).'),
(date '2026-04-17','Svitla p’iatnytsia. Icon of the Mother of God «Zhyvonosne dzherelo» (perekhidne sviatkuvannia u p’iatnytsiu Svitloho tyzhnia). Hieromartyr Symeona, Bishop Perskoho, and z nym Avdelaia and Ananii, presviteriv, mchch. Khusdazata (Usfazana), ievnukha, Fusyka, Azata, mts. Askytrei and inshykh bahatokh (344). Venerable Akakiia, Bishop Melitynskoho (ca. 435). Martyr Adriana (251). Saint Ahapita, papy Rymskoho (536).'),
(date '2026-04-18','Svitla Saturday. Venerable John, uchnia prp. Hryhoriia Dekapolita (820 – 850). Martyr Viktora, Zotyka, Zynona, Akyndyna and Severiana (303). Saint Kosmy, Confessor, Bishop Khalkidonskoho, and prp. Avksentiia (815 – 820). Martyr John Novoho z Yaniny (1526). Maksymivskoi Icon of the Mother of God (1299).'),
(date '2026-04-19','Antypaskha. 2th Sunday after Pascha, apostola Fomy. Venerable John Davnopechernyka (VIII). Martyr Feony, Khrystofora and Antonina (303). Hieromartyr Pafnutiia, Bishop Yerusalymskoho. Saint Heorhiia, Confessor, Bishop Antiokhii Pisidiiskoi (813 – 820). Saint Tryfona, patr. Konstantynopolskoho (933). Venerable Nykyfora, ihumena.'),
(date '2026-04-20','2th week after Pascha (Provody). Venerable Fedora Trykhiny. Saint Hryhoriia (593) and Anastasiia Synaita (599), patriarkhiv Antiokhiiskykh. Venerable Anastasiia, Abbot Synaiskoi hory (695). Martyr dytiaty Havryila Bilostotskoho (1690). Kiprskoi Icon of the Mother of God (392).'),
(date '2026-04-21','Hieromartyr Yanuariia, Bishop, and z nym sshchmchch. Prokula, Sossiia and Favsta, dyiakoniv, mchch. Dysyderiia, chyttsia, Yevtykhiia and Akutiona (ca. 305). Martyr Fedora, shcho in Perhii, materi his Fylypii, Dioskora, Sokrata and Dionisiia (138 – 161). Martyr Isaakiia, Apolosa and Kindrata (303). Saint Maksymiana, patriarkha Konstantynopolskoho (434).'),
(date '2026-04-22','Apostle Nafanaila, Luky and Klymenta (I). Venerable Fedora Sykeota, Bishop Anastasiupolskoho (613). Venerable Vitaliia (609 – 620).'),
(date '2026-04-23','Great Martyr Yuriia Peremozhtsia (303). Martyr tsarytsi Oleksandry (303). Martyr Anatoliia and Protoleona (303).'),
(date '2026-04-24','Martyr Savy Stratylata and z nym 70-kh voiniv (272). Venerable Savy Kyievo-of the Caves, in the Near Caves (XIII). Venerable Oleksiia, recluse Kyievo-of the Caves, in the Near Caves (XIII). Martyr Pasykrata and Valentyna (228). Martyr Yevseviia, Neona, Leontiia, Lonhyna and inshykh (303). Venerable Fomy, iurodyvoho (546 – 560). Venerable Yelyzavety, chudotvorytsi (VI – VIII). Molchenskoi Icon of the Mother of God (1 405).'),
(date '2026-04-25','Apostola and ievanhelista Marka (63). Tsarhorodskoi Icon of the Mother of God (1071).'),
(date '2026-04-26','3th Sunday after Pascha, Saints zhinok-myronosyts. Saint zhinok-myronosyts: Marii Mahdalyny, Marii Kleopovoi, Solomii, Ioanny, Marfy and Marii, Susanny and inshykh; pravednykh Yosyfa Arymafeiskoho and Nykodyma (perekhidne sviatkuvannia in 3-tiu nediliu after Pascha). Hieromartyr Vasyliia, Bishop Amasiiskoho. Righteous Hlafiry, divy (322). Venerable Ioanykiia Divychenskoho (XIII, Serb.). Right-believing Tamary, tsarytsi Hruzynskoi (perekhidne sviatkuvannia in 3-tiu nediliu after Pascha). Lvivskoi Icon of the Mother of God (perekhidne sviatkuvannia in nediliu after 23 kvitnia).'),
(date '2026-04-27','3th week after Pascha. Apostle vid 70-kh and sshchmch. Symeona, rodycha Hospodnoho (107). Venerable Stefana, Abbot Kyievo-of the Caves, Bishop Volodymyrskoho (1094). Righteous Yevlohiia, hostynnoho (IV).'),
(date '2026-04-28','Apostle vid 70-kh Yasona and Sosypatra, mts. Kerkyry, divy, and inshykh, iaki z nymy postrazhdaly (I). Martyr Dady, Maksyma and Kvyntyliana (286). Martyr Satorniia, Yakyskhola, Favstiana, Yanuariia, Marsaliia, Yefrasiia, Mammiia, Muryna, Zynona, Yevseviia, Neona and Vitaliia (ca. 63). Saint Kyryla, Bishop Turivskoho (1 183).'),
(date '2026-04-29','Dev’iatokh mchch. Kyzytskykh: Feohnyda, Rufa, Antypatra, Feostykha, Artemy, Mahna, Feodota, Favmasiia and Fylymona (286 – 299). Venerable Memnona, Wonderworker. Martyr Diodora and Rodopiana, deacon (284 – 305). Saint Vasyliia, Bishop Zakholmskoho (KhVI, Serb.). Martyr John Valakha (Rumun.).'),
(date '2026-04-30','Apostle Yakova Zevedeieva (44). Saint Donata, Bishop Yevrii (ca. 387). Znaidennia moshchiv sshchmch. Vasyliia, Bishop Amasiis- koho (IV). Znaidennia moshchiv svt. Mykyty Kyievo-of the Caves, Bishop Novhorodskoho (1558). Martyr Maksyma.'),
(date '2026-05-01','Prophet Yeremii (VI century BC). Hieromartyr Makariia, Metropolitan of Kyiv and vsiiei Rusy (1 497). Venerable Martyr Afonskykh: Yevfymiia (1814), Ihnatiia (1814) and Akakiia (1816). Venerable Martyr Vaty Persianyna (IV). Right-believing Tamary, tsarytsi Hruzynskoi (1213). Icon of the Mother of God, zvanoi «Nespodivana radist».'),
(date '2026-05-02','Saint Afanasiia the Great, Archbishop Oleksandriiskoho (373). Perenesennia moshchiv blhvv. kniaziv strastoterptsiv Borysa and Hliba, u sv. khreshchenni Romana and Davyda (1072 and 1 1 15). Saint Afanasiia, patr. Konstantynopolskoho, Lubenskoho Wonderworker (1 654). Martyr Espera and Zoi and ditei ikh Kyriaka and Feodula (II). Right-believing and rivnoap. tsaria Borysa, u sv. khreshchenni Mykhaila, enlightener bolhar (907, Bolh.).'),
(date '2026-05-03','4th Sunday after Pascha, pro paralizovanoho. Martyr Tymofiia and Mavry (ca. 286). Venerable Theodosius, Abbot Kyievo-of the Caves (1074). Venerable Petra, Wonderworker, Bishop Arhoskoho (X). Perenesennia moshchiv mch. Avraamiia Bolharskoho (1230) (perekhidne sviatkuvannia in 4-tu nediliu after Pascha). Righteous Tavyfy (I) (perekhidne sviatkuvannia in 4-tu nediliu after Pascha). Icon of the Mother of God: Uspinnia Kyievo-Pecherskoi, prynesenoi z Konstantynopolia (1073), Kyievo-Pecherskoi (z Antoniiem and Feodosiiem) (1085). P ravoslavna Ts erkva Ukrainy TRAVEN 139'),
(date '2026-05-04','4th week after Pascha. Martyr Pelahii, divy Tarsiiskoi (ca. 290). Hieromartyr Erazma, Bishop Formiiskoho (303). Hieromartyr Alviana, Bishop Aneiskoho, and uchniv his (304). Hieromartyr Sylvana, Bishop Hazkoho, and z nym 40 Martyrs (31 1).'),
(date '2026-05-05','Great Martyr Iryny (I – II). Icon of the Mother of God «Nevypyvana chasha» (1878).'),
(date '2026-05-06','Perepolovennia Pentecost. Righteous Iova Bahatostrazhdalnoho (ca. 2000 – 1500 do R. X.). Venerable Iova of Pochaiv (1 651). Martyr Varvara, voina, Vakkha, Kalymakha and Dionisiia (ca. 362). Martyr Parfeniia. Martyr Varvara, kolyshnoho rozbiinyka.'),
(date '2026-05-07','Zhaduvannia poiavy na nebi Khresta Hospodnoho in Yerusalymi (351). Martyr Akakiia, sotnyka (303). Venerable John Zedazniiskoho and uchniv his: Aviva, Bishop Nekreskoho, Anthony Martkobskoho, Davyda Haredzhyiskoho, Zynona Ilkatskoho, Fadeia Stepantsmydskoho, Ise (Iieseia), Bishop Tsylkanskoho, Yosyfa, Bishop Alaverdskoho, Isydora Samtaviiskoho, Mykhaila Ulumbiiskoho, Pirra Bretskoho, Stefana Khyrskoho and Shio Mhvymskoho (VI, Hruz.). Liubetskoi (XI) and Zhyrovytskoi (1470) Icon of the Mother of God.'),
(date '2026-05-08','Apostola and ievanhelista John Bohoslova (98 – 1 1 7). Venerable Arseniia the Great (449 – 450). Venerable Arseniia Pratseliubnoho (XIV) and Pymena, faster, (XII) of the Kyiv Caves, in the Far Caves. Pomynannia zahyblykh u II Svitovii viini.'),
(date '2026-05-09','Perenesennia moshchiv Saint and Wonderworker Nicholas z Myr Likiiskykh u m. Bar (1087). Prophet Isai (VIII century BC). Martyr Khrystofora (ca. 250). Venerable Shio Mhvymskoho (VI, Hruz.). Venerable Yosyfa Optynskoho (191 1).'),
(date '2026-05-10','5th Sunday after Pascha, pro samarianku. Apostola Symona Zylota (I). Saint Symona Kyievo-of the Caves, Bishop Volodymyrskoho and Suzdalskoho, u Blyzhnikh pecherakh (1226). Martyr Alfiia, Filadelfa, Kypriana, Onysyma, Erazma and inshykh (251). Martyr Isykhiia Antiokhiiskoho (IV). Venerable Isydory, iurodyvoi (IV). Blzh. Taisii Yehypetskoi (V). Kyievo-Bratskoi Icon of the Mother of God (1 654).'),
(date '2026-05-11','5th week after Pascha. Hieromartyr Mokiia (ca. 295). Equal-to-the-Apostles Kyryla (869) and Mefodiia (885), vchyteliv slov’ianskykh. Venerable Sofroniia, recluse Kyievo-of the Caves, in the Far Caves (XIII). Saint Nykodyma, Archbishop Serbskoho (1325).'),
(date '2026-05-12','Saint Epifaniia, Bishop Kiprskoho (403). Saint Hermana, patr. Konstantynopolskoho (740). Saint Savyna, Archbishop Kiprskoho (V), and Poluviia, Bishop Rynokyrskoho (V). Venerable Amphilochius of Pochaiv, in malii skhymi Yosyfa, Wonderworker Ilovetskoho. (1971). Den tezoimenytstva Blazhenniishoho Mytropolyta of Kyiv and vsiiei Ukrainy Epifaniia.'),
(date '2026-05-13','Leavetaking of the Feast of Perepolovennia Pentecost. Martyr Hlikerii, divy, and z neiu mch. Laodykiia, storozha in’iaznychnoho (ca. 1 17). Perenesennia moshchiv prmch. Makariia, arkhim. Kanivskoho, Abbot Pinskoho, Pereiaslavskoho Wonderworker (1 688). Martyr Oleksandra Rymskoho (284 – 305). Saint Pavsykakiia, Bishop Synadskoho (606). Saint Heorhiia, Confessor, z druzhynoiu Irynoiu and ditmy (IX). Venerable Yevfymiia Iverskoho (1028, Hruz.).'),
(date '2026-05-14','Martyr Isydora (251). Venerable Mykyty, recluse Kyievo-of the Caves, Bishop Novhorodskoho (1 108). Martyr Maksyma (ca. 250). Venerable Serapiona Syndonita (V). Saint Leontiia, patr. Yerusalymskoho (1 175).'),
(date '2026-05-15','Venerable Pakhomiia the Great (348). Saint Isai Kyievo-Mykhailivskoho, Bishop Rostovskoho, Wonderworker (1090). Venerable Isai Kyievo-of the Caves (1 1 15). Venerable Akhyliia, Bishop Laryssiiskoho (II).'),
(date '2026-05-16','Venerable Fedora Osviachenoho (368). Venerable ottsiv, iaki in lavri sv. Savy buly vbyti (614). Saint Oleksandra, Bishop Yerusalymskoho (213 – 250). Martyr Vita, Modesta and mts. Kryskentii (ca. 303). Blzh. otrokovytsi Muzy (V). Saint Heorhiia II, Bishop Mitylenskoho (IX).'),
(date '2026-05-17','6th Sunday after Pascha, pro slipoho. Apostle Andronika and sv. Yunii (I). Martyr Solokhona, Pamfamyra and Pamfalona, voiniv (284 – 305). Saint Stefana, patr. Konstantynopolskoho (893).'),
(date '2026-05-18','6th week after Pascha. Pam’iat svv. ottsiv simokh Vselenskykh Synaxis ofiv. Martyr Feodota Ankyrskoho, Petra, Dionisiia, Andriia, Pavla, mts. Khrystyny (249 – 251) and mtsts. simokh div: Oleksandry, Tekusy, Klavdii, Fainy, Yevfrasii, Mot- rony and Yulii (303). Martyr Symeona, Isaaka and Vakhtysiia (IV), Irakliia, Pavlyna, Venedyma, Davyda and Tarychana (693, Hruz.).'),
(date '2026-05-19','Hieromartyr Patrykiia, Bishop Pruskoho, and z nym trokh presviteriv: Akakiia, Menandra and Poliiena (ca. 100). Martyr Parfeniia Zhovkivskoho, Rymskoho (250). Martyr Kalufa Yehyptianyna (284 – 303). Venerable John, Bishop Hotskoho (VIII).'),
(date '2026-05-20','Leavetaking of the Feast of Pascha. Martyr Falaleia, Oleksandra and Asteriia (ca. 284). Martyr Askalona (ca. 287). Znaidennia moshchiv Saint Oleksiia, Metropolitan of Kyiv and vsiiei Rusy, Wonderworker (1 431).'),
(date '2026-05-21','Ascension of the Lord. Equal-to-the-Apostles Emperor Constantine and his mother Empress Helen.'),
(date '2026-05-22','Martyr Vasyliska (ca. 308). Pam’iat II Vselenskoho Synaxis ofu (381). Martyr John-Volodymyr, kn. Serbskoho (1015).'),
(date '2026-05-23','Venerable Mykhaila, Confessor, Bishop Synadskoho (821). Venerable Martyr Mykhaila, chentsia (IX). Znaidennia moshchiv svt. Leontiia Kyievo-of the Caves, Bishop Rostovskoho (1 1 64). Venerable Yefrosynii, Abbot Polotskoi (1 1 73).'),
(date '2026-05-24','7th Sunday after Pascha, Saints ottsiv I Vselenskoho Synaxis ofu. Tone 6. Venerable Symeona stylite na Dyvnii hori (596). Martyr Meletiia Stratylata, Stefana, John, Serapiona, iehyptianyna, Kalynyka, volkhva, Fedora and Favsta and z nymy 1218 voiniv z druzhynamy and ditmy (218).'),
(date '2026-05-25','7th week after Pascha. Tretie znaidennia hlavy Forerunner and Baptist of the Lord John (ca. 850). Hieromartyr Feraponta, Bishop Kiprskoho (IV). Saint Inokentiia, Archbishop Khersonskoho (1857).'),
(date '2026-05-26','Apostle vid 70-kh Karpa and Alfeia (I). Martyr Averkiia and mts. Oleny (I). Venerable John Psykhaita, spovidnyka (IX). Martyr Heorhiia Novoho (1515).'),
(date '2026-05-27','Hieromartyr Feraponta, Bishop Sardiiskoho (III). Martyr Feodory, divy, and mch. Dydyma, voina (304). Znaidennia moshchiv svtt. of Kyiv: Kypriana and Fotiia (1 472). Righteous John Rusyna, spovidnyka (1 730). Venerable Dodo Davydo-Haredzhyiskoho (596, Hruz.) (perekhidne sviatkuvannia in seredu after Voznesinnia).'),
(date '2026-05-28','Venerable Mykyty, Confessor, Bishop Khalkidonskoho (IX). Hieromartyr Yevtykhiia, Bishop Melitynskoho (I), Martyr Yelykonydy (244). Hieromartyr Elladiia, iepyskopa (VI – VII).'),
(date '2026-05-29','Leavetaking of the Feast of Voznesinnia of the Lord. Martyr Feodosii, divy Tyrskoi (307 – 308). Pam’iat I Vselenskoho Synaxis ofu (325). Venerable Martyr Feodosii, divy (726 – 730). Icon of the Mother of God, called «Sporuchnytsia hrishnykh» and «Nevtomne Oko».'),
(date '2026-05-30','Troitska pomynalna Saturday. Zvershuiemo pam’iat vsikh vid viku spochylykh pravoslavnykh khrystyian – ottsiv, materiv, brativ and sester nashykh. Venerable Isaakiia, Confessor, ihumena obyteli Dalmatskoi (383).'),
(date '2026-05-31','Day of the Holy Trinity. Holy Pentecost.'),
(date '2026-06-01','1th week after Pentecost. Zahalnytsia. Den Saint Dukha. Martyr Yustyna Filosofa and inshoho Yustyna, and z nymy Kharytona, Kharyty, Yevelpista, Iieraksa, Peona and Valeriana (166). Venerable Ahapita Kyievo-of the Caves, likaria bezvidplatnoho, in the Near Caves (ca. 1095). Kiprskoi Icon of the Mother of God (perekhidne sviatkuvannia in Den Saint Dukha).'),
(date '2026-06-02','Saint Nykyfora, Confessor, patr. Konstantynopolskoho (828). Great Martyr John Novoho, Suchavskoho (1330 – 1340). Hieromartyr Pofyna, Bishop Lionskoho, and tykh, shcho z nym postrazhdaly (177). Martyr Blandyny and mch. Pontyka Lionskykh (177). Kyievo-Bratskoi Icon of the Mother of God (1 654).'),
(date '2026-06-03','Martyr Lukyliana, Klavdiia, Ipatiia, Pavla, Dionisiia and mts. Pavly, divy (270 – 275). Hieromartyr Lukiana, Bishop, Maksiana, presbyter, Yuliana, deacon, mchch. Markeliana and Saturnyna in Belhii (81 – 96).'),
(date '2026-06-04','Saint Mytrofana, patr. Konstantynopolskoho (ca. 326). Martyr Frontasiia, Severyna, Severiana and Sylana (I). Martyr Konkordiia (ca. 175). Hieromartyr Astiia, Bishop Dyrrakhiiskoho (II). Venerable Zosymy, Bishop Vavylona Yehypetskoho (VI). Icon of the Mother of God «Sporuchnytsia hrishnykh», Koretskoi (1 622) (perekhidne sviatkuvannia in chetver 1-ho tyzhnia after Pentecost).'),
(date '2026-06-05','Hieromartyr Dorofeia, Bishop Tyrskoho (ca. 362). Perenesennia moshchiv blhv. Ihoria, kn. Chernihivskoho and of Kyiv (1 150). Saint Kostiantyna, Metropolitan of Kyiv and vsiiei Rusy (1 159). Martyr Markiana, Nykandra, Iperekhiia, Apolona, Leonida, Ariia, Horhiia, Seliniia, Iryniia and Pamvona (305 – 31 1). Venerable Fedora, Wonderworker (ca. VI). Venerable Anuviia, pustelnyka Yehypetskoho (IV – V). Venerable Dorofeia, z obyteli avvy Seryda (620). Ihorivskoi Icon of the Mother of God (1 1 47).'),
(date '2026-06-06','Leavetaking of the Feast of Pentecost. Venerable Vissariona, Wonderworker Yehypetskoho (IV). Venerable Ilariona Novoho (845). Prmtsts. div Arkhelai, Fekly and Susanny (293).'),
(date '2026-06-07','1th Sunday after Pentecost. Vsikh Saints. Tone 8. Martyr Feodota Ankyrskoho (303). Hieromartyr Markeliana, Bishop Rymskoho, and mchch. Klavdiia, Kyryna and Antonina (304). Hieromartyr Markela, Bishop Rymskoho, Sysyniia and Kyriaka, dyiakoniv, mchch. Smarahda, Larhiia, Aproniana, Saturnina, Papiia and Mavra, voiniv, and Kryskentiana, mtsts. Pryskily, Lukyny and Artemii, tsarivny (304 – 310). Martyr Kalerii (Valerii), Kyriakii and Marii in Kesarii Palestynskii (IV). Icon of the Mother of God Ternopilskoi and «Pom’iakshennia zlykh serdets» (Semystrilna) (perekhidni sviatkuvannia in nediliu vsikh Saints).'),
(date '2026-06-08','2th week after Pentecost. Great Martyr Fedora Stratylata (319). Venerable Yefrema, patr. Antiokhiiskoho (545). Venerable Zosymy Finikiiskoho (VI). Saint Fedora, Bishop Suzdalskoho (1023). Icon of the Mother of God «Daleshivska».'),
(date '2026-06-09','Saint Kyryla, Archbishop Oleksandriiskoho (444). Martyr Fekly, Marfy and Marii in Persii (346).'),
(date '2026-06-10','Hieromartyr Tymofiia, Bishop Pruskoho (361 – 363). Saint John (Maksymovycha), Metropolitan Tobolskoho (1 715). Venerable Syluana, skhymnyka Kyievo-of the Caves, in the Far Caves (XIII – XIV). Martyr Oleksandra, Antoniny, divy (ca. 313). Venerable Feofana Antiokhiiskoho (369). Saint Vassiana, Bishop Lavdiiskoho (409).'),
(date '2026-06-11','Apostle Varfolomiia and Varnavy (I). Saint Luky, Archbishop Simferopolskoho, Confessor (1961). Icon of the Mother of God «Dostoino ie» («Myluiucha») (X).'),
(date '2026-06-12','Venerable Onufriia the Great (IV). Venerable Petra Afonskoho (734). Venerable John, Andriia, Iraklemona and Feofila (IV).'),
(date '2026-06-13','Martyr Akylyny (293). Saint Tryfyliia, Bishop Levkusii Kiprskoi (ca. 370). Martyr Antoniny Nikeiskoi (284 – 305). Venerable Anny (826) and son of her John.'),
(date '2026-06-14','2th Sunday after Pentecost. Vsikh Saints zemli Ukrainskoi. Tone 1. NovoMartyrs and spovidnykiv, iaki in Ukraini and in inshykh zemliakh u KhKh st. za Khrysta and pravoslavnu viru postrazhdaly (perekhidne sviatkuvannia in 2-hu nediliu after Pentecost). Pror Yelyseia (IX century BC). Saint Mefodiia, patr. Konstantynopolskoho (847). Right-believing kn. Mstyslava, u sv. khreshchenni Heorhiia, Khorobroho (1 180). Venerable Yelyseia Sumskoho (KhV – KhVI). Vsikh prepodobnykh and bohonosnykh ottsiv, shcho na Sviatii Hori Afonskii prosiaialy (perekhidne sviatkuvannia in 2-hu nediliu after Pentecost).'),
(date '2026-06-15','3th week after Pentecost. Prophet Amosa (VIII century BC). Saint Mykhaila, pershoho Metropolitan of Kyiv and vsiiei Rusy (992). Martyr Vita, Modesta and Kryskentii, hoduvalnytsi (ca. 303). Martyr Duly Kylikiiskoho (305 – 313). Venerable Duly, strastoterptsia, Yehypetskoho. Venerable Iieronima Blazhennoho Strydonskoho (420). Saint Avhusty -'),
(date '2026-06-16','Saint Tykhona, Bishop Amafuntskoho (425). Hieromartyr Tyhriia, presbyter, and mch. Yevtropiia, chyttsia (ca. 404).'),
(date '2026-06-17','Martyr Manuila, Savela and Ismaila (362).'),
(date '2026-06-18','Martyr Leontiia, Ipatiia and Feodula (70 – 79). Venerable Leontiia, kanonarkha Kyievo-of the Caves, in the Far Caves (XIV).'),
(date '2026-06-19','Apostola Iudy, brother of of the Lord po ploti (ca. 80). Martyr Zosymy (II). Venerable Paisiia the Great (V). Venerable John Palestynskoho, pustelnyka (VI). Venerable Paisiia Khilandarskoho (KhVIII, Bolh.).'),
(date '2026-06-20','Hieromartyr Mefodiia, Bishop Patarskoho (312). Martyr Inny, Pinny and Rymmy (I – II). Hieromartyr Arystokliia, presbyter, Dymytriana, deacon, and mch. Afanasiia, chyttsia (ca. 306). Saint Levkiia, Confessor, Bishop Vruntysiopolskoho (V). Saint Myny Kyievo-of the Caves, Bishop Polotskoho (1 1 1 6). Righteous Nicholas Kavasyly (1397/98).'),
(date '2026-06-21','3th Sunday after Pentecost. Tone 2. Martyr Yuliana Tarsiiskoho (ca. 305). Hieromartyr Terentiia, Bishop Iconiiskoho (I). Venerable Yuliia, presbyter, and Yuliana, deacon (V). Martyr Archyla II, tsaria Iverskoho (744), and Luarsaba II, tsaria Kartalynskoho (1622, Hruz.).'),
(date '2026-06-22','4th week after Pentecost. Hieromartyr Yevseviia, Bishop Samosatskoho (380). Martyr Zynona and Ziny (304). Martyr Halaktiona and Yulianii.'),
(date '2026-06-23','Martyr Ahrypyny Rymlianky (III). Hieromartyr Yevstokhiia, presbyter, mchch. Haia, Proviia, Loliia, Urvana and inshykh (IV).'),
(date '2026-06-24','Nativity of the Honorable and Glorious Prophet, Forerunner and Baptist John.'),
(date '2026-06-25','Prmts. Fevronii, divy (ca. 304). Maniavskoi Icon of the Mother of God «Vyzvolytelka» (1 788).'),
(date '2026-06-26','Venerable Davyda Solunskoho (ca. 540). Venerable John, Bishop Hotskoho (VIII). Saint Dionisiia Kyievo-of the Caves, Archbishop Suzdalskoho (1385). ChERVEN BohosluzhBovi vkazivky 2026 178 Liddskoi (Rymskoi) (I), Tykhvynskoi (1383) and Niametskoi (1399) Icon of the Mother of God.'),
(date '2026-06-27','Venerable Samsona, hostynnoho (ca. 530). Righteous Ioany, myronosytsi (I). Venerable Sevira, presbyter (VI). Venerable Heorhiia Iverskoho Saintrtsia (1065, Hruz.). Venerable Martyna Turivskoho (1 150). Hieromartyr Kyryla (Lukarisa), patr. Konstantynopolskoho (1638).'),
(date '2026-06-28','4th Sunday after Pentecost. Tone 3. Perenesennia moshchiv mchch., bezsrr. and chudotvortsiv Kyra and John (412). Venerable Ksenofonta Robeiskoho, ihumena (1262). Venerable Pavla, likaria ( VII).'),
(date '2026-06-29','The Holy, Glorious and All-Praised Leaders of the Apostles Peter and Paul.'),
(date '2026-06-30','Synaxis of slavnykh and vsekhvalnykh 12-okh apostoliv: Petra, Andriia Pershozvannoho, Yakova Zevedeievoho, John Bohoslova, Fylypa, Varfolomiia, Fomy, Matfeia, Yakova Alfeievoho, Iudy Yakovoho, Symona Zylota and Matfiia. Volynskoi (KhKh st.), Balykinskoi (171 1) and Horbanivskoi (1 786) Icon of the Mother of God.'),
(date '2026-07-01','Bezsrr. Kosmy and Damiana, iaki in Rymi postrazhdaly (284). Martyr Potyta (II). Venerable Petra, patrykiia (854). Perenesennia moshchiv prp. John Rylskoho (1469). Venerable Nykodyma Saintrtsia (1809).'),
(date '2026-07-02','Pokladennia chesnoi ryzy the Most Holy Theotokos u Vlakherni (V). Saint Yuvenaliia, patr. Yerusalymskoho (ca. 458). Saint Fotiia, Metropolitan of Kyiv and vsiiei Rusy (1 431). Saint John (Maksymovycha), Archbishop Shankhaiskoho and San-Frantsyskoho, Wonderworker (1966). Okhtyrskoi (1 739) and Pozhaiskoi (KhVII) Icon of the Mother of God.'),
(date '2026-07-03','Martyr Yakynfa (108). Martyr Diomyda, Yevlampiia, Asklipiodota and mts. Holindukhy (II). Venerable Anatoliia, recluse, u Blyzhnikh pecherakh (XII), and inshoho Anatoliia, recluse, u Dalnikh pecherakh (XIII). Martyr Mokiia and Marka (IV). Venerable Oleksandra, founder of obyteli «Nevsypushchykh» (ca. 430). Saint Anatoliia, patr. Konstantynopolskoho (458).'),
(date '2026-07-04','Saint Andriia, Archbishop Krytskoho (740). Venerable Marfy, materi Symeona Dyvnohortsia (551). Martyr Feodota and Feodotii (108). Hieromartyr Fedora, Bishop Kyryneiskoho (310). Halatskoi Icon of the Mother of God.'),
(date '2026-07-05','5th Sunday after Pentecost. Tone 4. Venerable Afanasiia Afonskoho (1000). Martyr Ahnii (Anny) Rymskoi and Kyrylly (304). Venerable Lampada Irynopolskoho (X). Icon of the Mother of God, zvanoi «Ekonomissa».'),
(date '2026-07-06','6th week after Pentecost. Venerable Sysoia the Great (429). Venerable Sysoia, skhymnyka Kyievo-of the Caves, u Dalnikh pecherakh (KhVI). Znaidennia moshchiv prav. divy Yulianii, kn. Olshanskoi (XIII). Martyr Maryna, Marfy, Avdyfaksa, Avakuma, Kyryna, Valentyna, presbyter, Asteriia and inshykh bahatokh u Rymi (269). Hieromartyr Isavra, deacon, mchch. Inokentiia, Feliksa, Yermiia, Vasyliia, Perehryna, Rufa and Rufyna (III). Martyr Kointa Fryhiiskoho (ca. 283). Martyr Lukii, divy, and z neiu mchch. Ryksa, Anthony, Lukiana, Isydora, Diona, Diodora, Kutoniia, Aronosa, Kapyka and Satura (301).'),
(date '2026-07-07','Venerable Iova (1 621) and Theodosius (1 629) Maniavskykh. Venerable Fomy, shcho in Malei (X). Venerable Akakiia, pro iakoho rozpovidaietsia in Listvytsi (VI). Martyr Perehryna, Lukiana, Pompeia, Isykhiia, Papiia, Satornyna and Hermana (II). Hieromartyr Epikteta, presbyter, and prmch. Astiona, chentsia (290). Martyr Yevanhela (III – IV). Martyr Kyriakii Nikomydiiskoi (IV). P ravoslavna Ts erkva Ukrainy LYPEN 185 Vlakhernskoi Icon of the Mother of God.'),
(date '2026-07-08','Great Martyr Prokopiia (303). Icon of the Mother of God «Odyhitriia Vlakhernska-Kazanska» (1579).'),
(date '2026-07-09','Hieromartyr Pankratiia, Bishop Tavromeniiskoho (I). Hieromartyr Kyryla, Bishop Hortynskoho (III – IV). Venerable Martyr Patermufiia, Kopriia and mch. Oleksandra (IV). Saint Fedora, Bishop Edeskoho (IX).'),
(date '2026-07-10','Martyr 45-okh in Nikopoli Virmenskomu: Leontiia, Mavrykiia, Danyila, Anthony, Oleksandra, Yanykyta, Sysyniia, Meneia, Vyrylada and inshykh (ca. 319). Venerable Anthony Kyievo-of the Caves, founder of ukrainskoho chernetstva (1073). Venerable Syluana, skhymnyka Kyievo-of the Caves, in the Far Caves (XIII – XIV). Martyr Apolloniia (III). Martyr Vianora and Syluana (IV). Venerable Martyr pustelnykiv iehypetskykh, vohnem and dymom zakatovanykh (ca. 398).'),
(date '2026-07-11','Zhaduvannia chuda vmts. Yevfymii Vsekhvalnoi, because of iake pravoslav’ia utverdylos (451). Equal-to-the-Apostles Olhy, kniahyni Kyivskoi, u sviatomu khreshchenni Oleny (969). Hieromartyr Kindeia, presbyter (III – IV).'),
(date '2026-07-12','6th Sunday after Pentecost. Tone 5. Martyr Prokla and Ilariia (II). Venerable Mykhaila Maleina, ihumena (962). Martyr Fedora, variaha, and son of his John, in Kyievi (983). Martyr Holindukhy Perskoi, u sv. khreshchenni Marii (591). Venerable John (1005) and Havryila (X) Saintrtsiv (Hruz.). Venerable Paisiia Saintrtsia (1994). LYPEN BohosluzhBovi vkazivky 2026 188 Icon of the Mother of God «Troieruchytsia» ( VIII).'),
(date '2026-07-13','7th week after Pentecost. Synaxis of arkhanhela Havryila. Venerable Stefana Savaita (794). Saint Yuliana, Bishop Kenomaniiskoho (I). Martyr Serapiona (II – III). Martyr Markiana (258). Proslavlennia svt. Sofroniia (Kryshtalevskoho), Bishop Irkutskoho (1918).'),
(date '2026-07-14','Apostola vid 70-kh Akyly (I). Martyr Yusta Rymskoho (I). Venerable Eliia, chentsia (IV). Venerable Onysyma Mahneziiskoho, Wonderworker (IV). Right-believing Oskolda, pershomuch. of Kyiv, u sv. khreshchenni Nicholas (882). Venerable Stefana Makhrytskoho (1406).'),
(date '2026-07-15','Equal-to-the-Apostles kniazia of Kyiv Volodymyr, u sv. khreshchenni Vasyliia (1015). Martyr Kyryka and materi his Ulyty (ca. 305). Martyr Avudyma Tenedoskoho (IV). Den khreshchennia Rusy-Ukrainy.'),
(date '2026-07-16','Hieromartyr Afinohena Sevastiiskoho, Bishop, and desiatokh uchniv his (ca. 31 1). Martyr Pavla and mtsts. Alevtyny (Valentyny) and Khionii (308). Martyr Antiokha Sevastiiskoho, likaria (IV). Martyr Yulii, divy (ca. 440 abo 613). Pam’iat svv. ottsiv IV Vselenskoho Synaxis ofu (451). Venerable John Vyshenskoho, Saintrtsia (after 1 620).'),
(date '2026-07-17','Great Martyr Maryny (Marharyty) Antiokhiiskoi (IV). Perenesennia moshchiv prp. Lazaria Halysiiskoho.'),
(date '2026-07-18','Martyr Emiliana (363). Martyr Yakynfa Amastrydskoho (IV). Venerable John Bahatostrazhdalnoho, Kyievo-of the Caves, in the Near Caves (1 1 60). Venerable Pamvy, recluse Kyievo-of the Caves, in the Far Caves (124 1). Venerable Pamvy Nitriiskoho, pustelnyka (IV). LYPEN BohosluzhBovi vkazivky 2026 192'),
(date '2026-07-19','7th Sunday after Pentecost. Tone 6. Pam’iat Saints ottsiv shistokh Vselenskykh Synaxis ofiv (perekhidne sviatkuvannia in nediliu, naiblyzhchu do 16 lypnia). Venerable Makryny, sister of svt. Basil the Great (380). Venerable Diia Konstantynopolskoho, Abbot (ca. 430). Venerable Paisiia Kyievo-of the Caves, in the Far Caves (XIV). Blhvv. kn. Stefana (1427) and materi his kn. Mylytsi (1405), pravyteliv Serbskykh. Znaidennia moshchiv prp. Serafyma, Sarovskoho Wonderworker (1903).'),
(date '2026-07-20','8th week after Pentecost. Prophet Illi (IX century BC). Znaidennia moshchiv prmch. Afanasiia Beresteiskoho (1 649).'),
(date '2026-07-21','Prophet Yezekyilia (VI century BC). Venerable Symeona, iurodyvoho zarady Khrysta, and John, spivfaster his (ca. 590). Venerable Onufriia Movchaznoho and Onysyma, recluse, of the Kyiv Caves, u Blyzhnikh pecherakh (XII – XIII).'),
(date '2026-07-22','Myronosytsi rivnoap. Marii Mahdalyny (I). Perenesennia moshchiv sshchmch. Foky, Bishop Synopskoho (403 – 404).'),
(date '2026-07-23','Pochaivskoi Icon of the Mother of God (1 675). Hieromartyr Apollinariia, Bishop Raveniiskoho (ca. 75). Martyr Trofyma, Feofila and z nymy 13 mchch. (IV).'),
(date '2026-07-24','Great Martyr Khrystyny (ca. 300). Martyr blhvv. knn. Borysa and Hliba, u sv. khreshchenni Romana and Davyda (1015). Venerable Polikarpa, arkhim. Kyievo-of the Caves (1 182).'),
(date '2026-07-25','Uspinnia prav. Anny, materi the Most Holy Theotokos. Saint zhinok Olimpiady, deaconess (408 – 410), and Yevpraksii, divy Tavenskoi (413). Pam’iat V Vselenskoho Synaxis ofu (553).'),
(date '2026-07-26','8th Sunday after Pentecost. Tone 7. Hieromartyr Yermolaia, Yermypa and Yermokrata, presviteriv Nikomydiiskykh (ca. 305). Prmts. Paraskevy Rymskoi (II). Venerable Moiseia Uhryna, Kyievo-of the Caves, in the Near Caves (ca. 1043). Venerable Moiseia, Wonderworker Kyievo-of the Caves, in the Far Caves (XIII – XIV). Saint Yosyfa (Neliubovycha-Tukalskoho), Metropolitan of Kyiv, Halytskoho and vsiiei Rusy (1 675).'),
(date '2026-07-27','9th week after Pentecost. Great Martyr and tsilytelia Panteleimona (305). Venerable Anfisy, ihumeni, and 90 sester her (VIII). Equal-to-the-Apostles Klymenta, Bishop Okhrydskoho (916), Nauma, Savy, Horazda and Anheliara (IX-X, Bolh.). Venerable Hermana Aliaskynskoho (1837).'),
(date '2026-07-28','Apostle vid 70-kh: Prokhora, Nykanora, Tymona and Parmena, dyiakoniv (I). Martyr Yuliana (I), Yevstafiia (ca. 316) and Akakiia (ca. 321). Venerable Iova Uholskoho (1985). Smolenskoi Icon of the Mother of God «Odyhitriia» («Providnytsia», prynesena z Tsarhoroda u 1046 rotsi).'),
(date '2026-07-29','Martyr Kalynyka Kilikiiskoho (III – IV). Martyr Serafymy, divy (II). Martyr Feodotii and trokh ditei her (ca. 304). Venerable Martyr Mykhaila Edeskoho, chentsia (IX). Martyr Yevstafiia Mtskhetskoho (589, Hruz.). Martyr Danyila (Kushnira), Mliivskoho (1 766).'),
(date '2026-07-30','Apostle vid 70-kh: Syly, Syluana, Kryskenta, Epeneta and Andronika (I). Martyr John Voina (IV). Hieromartyr Polikhroniia, Bishop Vavylonskoho, Parmeniia, Yelymy and Khrysotelia, presviteriv, Luky and Muko, dyiakoniv, mchch. Avdona and Senisa, kniaziv Perskykh, and Olimpiia and Maksyma (ca. 251). Hieromartyr Valentyna (Ualentyna), iepyskopa Italiiskoho, and trokh uchniv his – mchch. Prokuly, Yefyva and Apolloniia and prav. Avundiia (ca. 273). Venerable Anheliny, pravytelky Serbskoi (1520)'),
(date '2026-07-31','Forefeast vynesennia drev chesnoho and zhyvotvorchoho Khresta Hospodnoho. Righteous Yevdokyma Kapadokiitsia (IX). Martyr Yulyty Kesariiskoi (304 – 305).'),
(date '2026-08-01','Vynesennia chesnykh drev zhyvotvorchoho Khresta of the Lord. Simokh mchch. Makkaveievykh: Avyma, Antonina, Huriia, Yeleazara, Yevsevona, Alima and Markela, materi their mts. Solomonii and vchytelia ikhnoho mch. Yeleazara (1 66 BC). Martyr in Perhii Pamfiliiskii: Leontiia, Atiia, Oleksandra, Kyndeia, Mynsyfeia, Kyriaka, Myneona, Katuna and Evkleia (III).'),
(date '2026-08-02','9th Sunday after Pentecost. Tone 8. Perenesennia z Yerusalyma do Konstantynopolia moshchiv pershoMartyr arkhidyiak. Stefana (ca. 428) and znaidennia moshchiv pravv. Nykodyma, Hamaliila and son of his Aviva. Hieromartyr Stefana, iepyskopa Rymskoho, and inshykh z nym (257).'),
(date '2026-08-03','10th week after Pentecost. Venerable Isaakiia, Dalmata and Favsta (IV – V). Martyr Razhdena, persa (457, Hruz.). Venerable Kosmy, pustelnyka (VI).'),
(date '2026-08-04','Simokh otrokiv u Efesi: Maksymiliana, Yamvlykha, Martyniana, John, Dionisiia, Eksakustodiana (Kostiantyna) and Antonina (ca. 250; 408 – 450). Prmts. Yevdokii (362 – 364). Martyr Yelevferiia (IV).'),
(date '2026-08-05','Forefeast Preobrazhennia Hospodnoho. Martyr Yevsyhniia Antiokhiiskoho (362). Hieromartyr Anfira (236) and Fabiana (250), iepyskopiv Rymskykh. Martyr Pontiia Rymlianyna (ca. 257). Martyr Kantydiia, Kantydiana and Syvela, in Yehypti. Righteous Nonny, deaconess, materi svt. Hryhoriia Bohoslova (374). Venerable Feoktysta of the Caves, Bishop Chernihivskoho († 1 123).'),
(date '2026-08-06','Transfiguration of Our Lord, God and Savior Jesus Christ.'),
(date '2026-08-07','Afterfeast Preobrazhennia Hospodnoho. Venerable Martyr Dometiia Perskoho, iierodyiak. and dvokh uchniv his (363). Venerable Pymena Bahatokhvoroblyvoho, Kyievo-of the Caves, in the Near Caves (1 1 10). Venerable Pymena, faster Kyievo-of the Caves, in the Far Caves (XIII – XIV). Venerable Merkuriia Kyievo-of the Caves, Bishop Smolenskoho, in the Near Caves (1239). Martyr Maryna and Asteriia (260). Venerable Ora Fivaidskoho (ca. 390). Prmts. Potamii, chudotvorytsi. Venerable Theodosius Novoho, likaria (IX–X). Saint Iierofeia, Bishop Uhorskoho (X). Saint Stefana I, korolia Uhorshchyny (1038). Venerable Feodory Sykhlivskoi (XVIII, Rum.).'),
(date '2026-08-08','Saint Emiliana, Confessor, Bishop Kyzytskoho (815 – 820). Venerable Hryhoriia, Iconopystsia Kyievo-of the Caves, in the Near Caves (XII). Saint Myrona, Wonderworker, Bishop Krytskoho (ca. 350). Martyr Yelevferiia and Leonida. Venerable Hryhoriia Synaita (XIV).'),
(date '2026-08-09','10th Sunday after Pentecost. Tone 1. Apostola Matfiia (ca. 63). Martyr Anthony Oleksandriiskoho. Venerable Psoia Yehypetskoho (IV). Martyr Yuliana, Markiana, John, Yakova, Oleksiia, Dymytriia, Fotiia, Petra, Leontiia, Marii, patrykii, and in. (730).'),
(date '2026-08-10','1 1th week after Pentecost. Hieromartyr Lavrentiia, arkhideacon, Syksta II, iepyskopa, Felikysyma and Ahapita, dyiakoniv, mch. Romana, Rymskykh (258).'),
(date '2026-08-11','Hieromartyr Yevpla, arkhideacon (304). Venerable Martyr Fedora and Vasyliia of the Kyiv Caves, in the Near Caves (1098). Venerable Fedora, kn. Ostrozkoho, Kyievo-of the Caves, in the Far Caves (ca. 1 438). Martyr Susanny, divy, and z neiu sshchmchch. Haia, iepyskopa Rymskoho, Havyniia, presbyter, mchch. Klavdiia, Maksyma, Prepedyhny, Oleksandra and Kufiia (295 – 296).'),
(date '2026-08-12','Martyr Fotiia and Anykyty and bahatokh with nymy (305 – 306). Hieromartyr Oleksandra, Bishop Komanskoho (III). Martyr Pamfila and Kapitona.'),
(date '2026-08-13','Leavetaking of the Feast of Preobrazhennia of the Lord. Venerable Maksyma Spovidnyka (662). Martyr Ipolyta, Iryneia, Avundiia and mts. Konkordii in Rymi (258).'),
(date '2026-08-14','Forefeast Uspinnia the Most Holy Theotokos. Prophet Mykheia (VIII century BC). Perenesennia moshchiv prp. Theodosius Kyievo-of the Caves (1091). Hieromartyr Markela, Bishop Apameiskoho (ca. 389).'),
(date '2026-08-15','Dormition of Our Most Holy Lady Theotokos and Ever-Virgin Mary. Icon of the Mother of God of the Kyiv Caves.'),
(date '2026-08-16','1 1th Sunday after Pentecost. Tone 2. Afterfeast Uspinnia. Perenesennia z Edesy do Konstantynopolia Nerukotvornoho obrazu (ubrusa) Lord Isusa Khrysta (944). Martyr Diomyda, likaria (298). Martyr 33-okh palestynskykh. Venerable Kherymona Yehypetskoho (IV). Martyr kn. Kostiantyna (1714, Rum.). Venerable Yosyfa Isykhasta (1959). Icon of the Mother of God, nazvanoi «Dodannia rozumu» (perekhidne sviatkuvannia in pershu nediliu after 15 serpnia).'),
(date '2026-08-17','12th week after Pentecost. Hieromartyr Myrona, presbyter (250). Venerable Alipiia, Iconopystsia Kyievo- of the Caves, in the Near Caves (ca. 1 1 1 4). Martyr Pavla, mts. Yulianii and in. (ca. 273). Martyr Firsa, Levkiia, Koronata and voiniv ikhnikh (249 – 251). Martyr Patrokla (270 – 275). Martyr Stratona, Fylypa, Yevtykhiana and Kypriana (ca. 303).'),
(date '2026-08-18','Martyr Flora and Lavra (II). Martyr Yerma, Serapiona and Poliiena (II). Hieromartyr Emiliana, iepyskopa, and z nym Ilariona, iierom., mchch. Dionisiia and Yermypa (ca. 300). Saint John (674) and Heorhiia (683), patriarkhiv Konstantynopolskykh. Venerable Makariia, ihumena Pelikytskoho (ca. 830). Venerable John Rylskoho (946, Bolh.). Icon of the Mother of God, nazvanoi «Vsetsarytsia» ( XVII).'),
(date '2026-08-19','Martyr Andriia Stratylata and z nym 2593 Martyrs (284 – 305). Martyr Tymofiia, Ahapiia and mts. Fekly (ca. 304). P ravoslavna Ts erkva Ukrainy SERPEN 213'),
(date '2026-08-20','Prophet Samuila (XI century BC). Hieromartyr Sevyra, presbyter and mch. Memnona and z nymy 37 Martyrs (304).'),
(date '2026-08-21','Apostle vid 70-kh Fadeia (ca. 44). Martyr Vassy and her ditei: mchch. Feohniia, Ahapiia and Pista (305 – 31 1). Venerable Avraamiia Pratseliubnoho, of the Caves, in the Near Caves (XII – XIII). SERPEN BohosluzhBovi vkazivky 2026 214'),
(date '2026-08-22','Martyr Ahafonyka, Zotyka, Feoprepiia (Boholipa), Akyndyna, Severiana and inshykh (305 – 31 1). Hieromartyr Afanasiia, Bishop Tarsiiskoho (270 – 275), prp. Anfusy (ca. 298) and her sluh: mchch. Kharysyma and Neofita (270 – 275). Martyr Yevlalii, divy (ca. 303). Hieromartyr Horazda, Bishop Bohemskoho and Moravo-Sylezkoho (1942, Chekh.). Hruzynskoi Icon of the Mother of God (1650).'),
(date '2026-08-23','12th Sunday after Pentecost. Tone 3. Leavetaking of the Feast of Uspinnia the Most Holy Theotokos. Hieromartyr Iryneia, Bishop Lionskoho (202). Martyr Luppa Salonikiiskoho (IV). Venerable Yevtykhiia, ihumena (ca. 540) and Florentiia (547). Saint Kalynyka, patr. Konstantynopolskoho (705).'),
(date '2026-08-24','13th week after Pentecost. Hieromartyr Yevtykhiia, iepyskopa, uchnia ap. John Bohoslova (I). Martyr Tationa (305). Martyr Siry, divy Perskoi (558). Venerable Heorhiia Lymniota (ca. 716). Equal-to-the-Apostles prmch. Kosmy Etoliiskoho, iierom. (1779).'),
(date '2026-08-25','Perenesennia moshchiv ap. Varfolomiia (VI). Apostle vid 70-kh Tyta, Bishop Krytskoho (I). Saint Varsysa and Yevlohiia, iepysko- piv Edeskykh, and Protohena, Bishop Kariiskoho, spovidnyka (IV). Saint Myny, patr. Konstantynopolskoho (536 – 552).'),
(date '2026-08-26','Martyr Adriana and Natalii (305 – 31 1).'),
(date '2026-08-27','Venerable Pymena the Great (ca. 450). Venerable sshchmch. Kukshi and uchnia his mch. Nykona, Pymena, faster, of the Kyiv Caves, in the Near Caves (after 1 1 1 4). Saint Osii, Confessor, Bishop Kordovskoho (359). Saint Liveriia, Confessor, iepyskopa Rymskoho (366). Venerable Pymena Palestynskoho (ca. 602). Martyr Anfisy Novoi. Venerable Savy Venefalskoho.'),
(date '2026-08-28','Venerable Moiseia Muryna (ca. 400). Synaxis of prpp. ottsiv of the Kyiv Caves, shcho in the Far Caves (prp. Theodosius) spochyvaiut: Theodosius (1074), Moiseia, Wonderworker (XIII – XIV), Lavrentiia, zatvorn. (XIII – XIV), Ilariona, skhymn. (1066), Pafnutiia, zatvorn. (XIII), Martyriia, dyiak. (XIV), Fedora, kn. Ostrozkoho (ca. 1438), Afanasiia, zatvorn. (XIII), Dionisiia, iierom., zatvorn. (KhV), Feofila, Bishop Novhorodskoho (ca. 1482), Zynona, posn. (XIV), Hryhoriia, zatvorn. (XIV), Ipatiia, tsilytelia (XIV), sshchmch. Lukiana (1243), Yosyfa Bahatokhvoroblyvoho (XIV), Pavla Poslushnoho (XIII), Sysoia, skhymn. (XIII), Nestora, neknyzhn. (XIV), Pamvy, zatvorn. (1241), Fedora, movchaln. (XIII), Sofroniia, zatvorn. (XIII), Pankratiia, iieromon., zatvorn. (XIII), Anatoliia, zatvorn. (XIII), Ammona, zatvorn. (XIII),'),
(date '2026-08-29','Beheading of the Honorable Head of the Holy, Glorious Prophet, Forerunner and Baptist John.'),
(date '2026-08-30','13th Sunday after Pentecost. Tone 4. Saint Oleksandra (340), John faster (595) and Pavla Novoho (784), patriarkhiv Konstantynopolskykh. Venerable Khrystofora Rymlianyna (VI). Venerable Fantyna Solunskoho, Wonderworker (IX – X). Saint Serbskykh: Savy I (1237), Arseniia (1266), Savy II (1271), Yevstafiia (ca. 1285), Yakova (1292), Nykodyma (1325), Danyila (1338), arkhiiepyskopiv; Ioanykiia (1354), Yefrema (after 1395), Spyrydona (1388), Makariia (1574), Havryila (1659), patriarkhiv, and Hryhoriia, iepyskopa. Venerable Oleksandra Svirskoho (1533). Saint Varlaama, Metropolitan Moldovskoho (1657, Rum.).'),
(date '2026-08-31','1 4th week after Pentecost. Pokladennia chesnoho poiasa the Most Holy Theotokos (395 – 408). Hieromartyr Kypriana, Bishop Karfahenskoho (258). Saint Hennadiia, patr. Konstantynopolskoho (471). Saint John II, Metropolitan of Kyiv and vsiiei Rusy († 1089). Pam’iat vidnovlennia pravoslavnoi iierarkhii Kyivskoi Mytropolii (1 620). VERESEN BohosluzhBovi vkazivky 2026 220'),
(date '2026-09-01','Pochatok indyktu – tserkovne novolittia. Venerable Symeona stylite (459) and materi his Marfy (ca. 428). Synaxis of Vinnytskykh Saints. Hieromartyr Aifala Perskoho, deacon (380). Martyr 40 div, posnyts, and sshchmch. Amuna, deacon, ikhnoho vchytelia (IV). Martyr Kalisty and brativ her, mchch. Yevoda and Yermohena (309). Righteous Isusa Navyna (KhVI century BC). Synaxis of the Most Holy Theotokos in Miasynskii obyteli (in pam’iat znaidennia Yii Icon, 864).'),
(date '2026-09-02','Venerable Anthony (1073) and Theodosius (1074) of the Kyiv Caves. Martyr Mamanta (275), batka his Feodota and materi Rufiny (III). Venerable John faster, patr. Konstantynopolskoho (595). Martyr 3628 in Nikomydii (III – IV).'),
(date '2026-09-03','Hieromartyr Anfima, Bishop Nikomydiiskoho, and z nym sshchmch. Feofila and Myhdoniia, dyiakoniv, mchch. Dorofeia, Mardoniia, Petra, Indysa, Horhoniia, Zynona, Yevfymiia and mts. Domny, divy (302). Venerable Feoktysta Palestyn skoho, Abbot, spivfaster prp. Yevfymiia the Great (467). Saint Fivy Korynfskoi, deaconess (I). Martyr Vasylisy Nikomydiiskoi (309). Hieromartyr Arystiona, Bishop Oleksandriiskoho. Saint Ioanykiia, patr. Serbskoho (1354). Pisydiiskoi Myrotochyvoi Icon of the Mother of God ( VI).'),
(date '2026-09-04','Hieromartyr Vavyly, Bishop Antiokhiiskoho, and z nym trokh otrokiv: Urvana, Prylidiana, Epoloniia and materi their Khrystoduly (ca. 251). Prophet Moiseia Bohovydtsia (1531 do R. X.). Znaidennia moshchiv svt. Ioasafa (Horlenka), Bishop Bilhorodskoho (191 1). Martyr Yermionii, dochky ap. Fylypa, deacon (ca. 1 17). Martyr Vavyly Nikomydiiskoho and z nym 84 uchniv (IV). Martyr Fedora, Miana, Yuliana and Kiona (305 – 31 1). Icon of the Mother of God «Neopalyma kupyna».'),
(date '2026-09-05','Prophet Zakharii and prav. Yelyzavety, batkiv sv. John Forerunner (I). Venerable Martyr Afanasiia, Abbot Beresteiskoho (1 648). Konchyna blhv. kn. Hliba, in khreshchenni Davyda (1015). Martyr Fyfaila and sister of his Fivei (Vyvei) (98 – 138). Martyr Sarvyla. Martyr Raisy (Iraidy) (ca. 308). Martyr Yuventyna and Maksyma, voiniv (361 – 363). Martyr Urvana, Fedora, Medymna and z nymy 77 cholovikiv z tserkovnoho chynu, iaki in Nikomydii postrazhdaly (370). Martyr Avdiia (Avyda) Perskoho (V).'),
(date '2026-09-06','1 4th Sunday after Pentecost. Tone 5. Spomyn chuda arkhistratyha Mykhaila in Khonakh (Kolosakh) (I V). Martyr Yevdoksiia, Zynona and Makariia (31 1 – 312). Venerable Arkhypa in Khonakh (IV). Martyr Romyla Rymskoho and z nym bahatokh inshykh (105 – 1 15). Hieromartyr Kyryla, Bishop Hortynskoho (III – IV). Hieromartyr Favsta, presbyter, Aviva, deacon, and z nymy 1 1 Martyrs: Kyriaka and inshykh (ca. 250). Venerable Davyda Hermopolskoho (VI). Saint Mykhaila († ca. 1073) and Maryna († ca. 1095), iepp. Yur’ivskykh. Saint Lazaria († 1 1 1 7) and Sylvestra († 1 123), iepp. Pereiaslavskykh, ihumm. Vydubytskykh. Kyievo-Bratskoi (1 654) and Arapetskoi (Araviiskoi) Icon of the Mother of God.'),
(date '2026-09-07','15th week after Pentecost. Forefeast Rizdva the Most Holy Theotokos. Martyr Sozonta (ca. 304). Venerable Martyr Makariia, arkhim. Kanivskoho, Ovrutskoho, Pereiaslavskoho Wonderworker (1 678). Apostle vid 70-kh Yevoda (66) and Onysyfora (after 67). Martyr Yevpsykhiia Kesariiskoho (II). Venerable Luky Kappadokiiskoho (X). Icon of the Mother of God «Vinytska» («Vinnytsko-Rizhetska») (XVIII). Poriadok chytannia za kalendrem: Hal., 202 zach., II, 1 1 – 16. Mk., 21 zach., V, 24 – 34 (za ponedilok). Hal., 204 zach., II, 21 – III, 7. Mk., 22 zach., VI, 1 – 7 (pid zachalo, za vivtorok). Venerable Martyr: Ef., 233 zach., VI, 10 – 17. In., 52 zach., XV, 17 – XVI, 2. Sluzhba prmch. Makariia Kanivskoho, slavoslivna zvershuiemo razom with shesterychnoiu sluzhboiu peredsviata Rizdva Pre -'),
(date '2026-09-08','Nativity of Our Most Holy Lady Theotokos and Ever-Virgin Mary. Icons of the Mother of God of Pochaiv, Kholm, and others.'),
(date '2026-09-09','Afterfeast Rizdva the Most Holy Theotokos. Pravv. Bohoottsiv Ioakyma and Anny. Martyr Severiana Sevastiiskoho (320). Znaidennia and perenesennia moshchiv svt. Theodosius, Archbishop Chernihivskoho (1896). Venerable Feofana, spovidnyka and faster (ca. 300). Martyr Kharytona and Stratora (Stratonika). Saint Mykyty Konstantynopolkoho (XII). Pam’iat III Vselenskoho Synaxis ofu (431). VERESEN BohosluzhBovi vkazivky 2026 226'),
(date '2026-09-10','Martyr Mynodory, Mytrodory and Nimfodory (305 – 31 1). Venerable Pavla Poslushnoho, Kyievo-of the Caves, in the Far Caves (XIII – XIV). Apostle vid 70-kh: Apolosa (Apeliia), Lukiia and Klymenta (I). Martyr Varypsava (II). Right-believing Pulkherii, imperatrytsi Vizantiiskoi (453). Saint Petra and Pavla, iepp. Nikeiskykh (IX).'),
(date '2026-09-11','Venerable Feodory Oleksandriiskoi (474 – 491). Martyr Dymytriia, Yevanfii, druzhyny his, and Dymytriana, son of ikhnoho (I). Martyr Diodora and Dydyma, Syriiskykh. Martyr Yevdokii (Ii) Rymlianky (362 – 364). Venerable Yefrosyna Palestynskoho (IX). P ravoslavna Ts erkva Ukrainy VERESEN 227'),
(date '2026-09-12','Saturday before Vozdvyzhenniam. Leavetaking of the Feast of Rizdva the Most Holy Theotokos. Hieromartyr Avtonoma, Bishop Italiiskoho (313). Hieromartyr Yuliana, presbyter and z nym 40 Martyrs (IV). Hieromartyr Fedora, Bishop Oleksandriiskoho. Hieromartyr Kornuta, Bishop Nikomydiiskoho (249 – 259).'),
(date '2026-09-13','15th Sunday after Pentecost, before Vozdvyzhennia. Tone 6. Forefeast Vozdvyzhennia chesnoho Khresta Hospodnoho. Pam’iat onovlennia (osviachennia) khramu Voskresinnia Khrystovoho in Yerusalymi (335). Hieromartyr Kornyliia Sotnyka, Bishop (I). Martyr Kronida, Leontiia and Serapiona (ca. 237). Martyr Selevka and Stratonika (III). Martyr Makroviia and Hordiana (320). Hieromartyr Yuliana, presbyter (IV). Martyr Illi, Zotyka, Lukiana and Valeriana (320). Venerable Petra in Atroi (IX). Great Martyr Ketevani, tsarytsi Kakhetynskoi (1624, Hruz.). VERESEN BohosluzhBovi vkazivky 2026 228'),
(date '2026-09-14','Exaltation of the Honorable and Life-Giving Cross of the Lord.'),
(date '2026-09-15','Afterfeast Vozdvyzhennia. Great Martyr Mykyty (ca. 372). Znaidennia moshchiv svt. Akakiia, Confessor, Bishop Melitynskoho (III). Martyr Maksyma, Feodota, mts. Askliady (Asklipiodoty) (305 – 31 1). Martyr Porfyriia Efeskoho (361). Znaidennia moshchiv pershoMartyr arkhidyiak. Stefana (415). Venerable Filofeia, presbyter, in Malii Azii (X). Saint Yosyfa, Bishop Alaverdskoho (570, Hruz.). Saint Symeona, Archbishop Solunskoho (1429). Novomykytskoi Icon of the Mother of God (372).'),
(date '2026-09-16','Great Martyr Yevfymii Vsekhvalnoi (304). Martyr Sevastiany (I). Martyr Melityny (II). Martyr Viktora and Sosfena (ca. 304). Venerable Dorofeia, pustelnyka Yehypetskoho (IV). Martyr Liudmyly, kn. Cheskoi (927). Martyr brativ Yosyfa and Isaka (808, Hruz.). Saint Kypriana, Metropolitan of Kyiv and vsiiei Rusy, Wonderworker (1 406). Icon of the Mother of God, zvanoi «Zhliansia na smyrennia» (1420).'),
(date '2026-09-17','Martyr Viry, Nadii, Liubovi and materi ikh Sofii (ca. 137). Martyr Feodotii (ca. 230) and Ahafoklii. Martyr 156: sshchmchch. Peliia and Nila, iepp. Yehypetskykh, Zynona, presbyter, mchch. Patermufiia, Illi and inshykh (310). Saint Ioakyma (Pani), patr. Oleksandriiskoho (1567). Konstantynopolskoi Icon of the Mother of God (1071).'),
(date '2026-09-18','Venerable Yevmeniia, Bishop Hortynskoho (VII). Martyr Ariadny Fryhiiskoi (II). Martyr Sofii and Iryny (III). Martyr Kastora. Martyr Bydzyny, Shalvy and Elizbara, kniaziv Ksanskykh (1660, Hruz.). Molchenskoi Icon of the Mother of God (1 405).'),
(date '2026-09-19','Saturday after Vozdvyzhennia. Martyr Trofyma, Savatiia and Dorymedonta (276). Venerable Martyr Zosymy, pustelnyka (IV). Right-believing kn. Ihoria Chernihivskoho and of Kyiv (1 1 47).'),
(date '2026-09-20','1 6th Sunday after Pentecost, after Vozdvyzhennia. Tone 7. Great Martyr Yevstafiia Plakydy, druzhyny his Feopistii and syniv ikhnikh Ahapiia and Feopista (ca. 1 18). Martyr and spovv. Mykhaila, kn. Chernihivskoho, and boiaryna his Fedora, chudotvortsiv (1245). Venerable and blhv. kn. Chernihivskoho Oleha Romanovycha (ca. 1285). Perenesennia moshchiv mch. Parfeniia Zhovkivskoho, Rymskoho na Halychynu (1 784) (perekhidne sviato u nediliu after Vozdvyzhennia).'),
(date '2026-09-21','1 7th week after Pentecost. Leavetaking of the Feast of Vozdvyzhennia Zhyvotvorchoho Khresta of the Lord. Apostle vid 70-kh Kodrata (ca. 130). Znaidennia moshchiv svt. Dymytriia (Tuptala), Metropolitan Rostovskoho (1 752). Hieromartyr Ipatiia, iepyskopa, and Andriia, presvit. (ca. 730 – 735). Saint Isakiia and Meletiia, iepp. Kiprskykh. Martyr Yevseviia and Pryska.'),
(date '2026-09-22','Prophet Jonah (VIII century BC). Hieromartyr Foky, Bishop Synopskoho (1 17). Venerable Jonah, presbyter (IX), batka sshchmch. Feofana, Bishop, tvortsia kanoniv, and prmch. Fedora, Nakreslenykh. Martyr Foky Synopskoho, sadivnyka (ca. 320). Righteous Petra, kolyshnoho mytaria (VI).'),
(date '2026-09-23','Zachattia chesnoho slavnoho proroka, Forerunner and Baptist John. Venerable zhinok Ksanfypy and Poliksenii (109). Martyr Iraidy (Raisy), divy (ca. 308). Martyr Andriia, John and syniv Ioanovykh Petra and Antonina (IX).'),
(date '2026-09-24','Equal-to-the-Apostles Fekly, pershomts. (I). Venerable Theodosius Maniavskoho (1 629). Venerable Kopriia Palestynskoho (530). Saint kn. Stefana Serbskoho (1224) and son of his sv. kn. Vladyslava Serbskoho (1230 – 1239). Venerable Syluana Afonskoho (1938).'),
(date '2026-09-25','Venerable Yefrosynii Oleksandriiskoi (V). Venerable Serhiia, Abbot Radonezkoho, Wonderworker (1392). Venerable Martyr Pafnutiia iehyptianyna and z nym 546 mchch. (III). Venerable Yefrosynii, kniazhny Chernihivskoi, Abbot Suzdalskoi (1250).'),
(date '2026-09-26','Apostola and ievanhelista John Bohoslova (pochatok II).'),
(date '2026-09-27','1 7th Sunday after Pentecost. Tone 8. Martyr Kalistrata and voiniv his: Himnasiia and inshykh (304). Apostle vid 70-kh: Marka, Arystarkha and Ziny (I). Martyr Yepykharii Rymskoi (III). Venerable Ihnatiia Kappadokiiskoho, Abbot (X).'),
(date '2026-09-28','18th week after Pentecost. Venerable Kharytona Spovidnyka (ca. 350). Synaxis of prepodobnykh ottsiv of the Kyiv Caves, iaki in the Near Caves (prp. Anthony) spochyvaiut: Anthony, founder of Lavry (1073), Prokhora, Wonderworker (1 107), John, faster (XII), Yulianii, divy, kn. Olshanskoi (ca. 1550), prmchch. Vasyliia and Fedora (1098), Polikarpa, arkhim. Kyievo-of the Caves (1 182), Varlaama, Abbot Kyievo-of the Caves (1065), Nykona, Abbot Kyievo-of the Caves (1088), Damiana, presvit., tsilytelia (1071), Nykodyma, prosfornyka (XII), Lavrentiia, zatvorn., Bishop Turivskoho (XII), Afanasiia, zatvorn. (ca. 1 176), Erazma (ca. 1 160), Luky, Iconoma Kyievo-of the Caves (XIII), Ahapita, likaria bezvidplatnoho (ca. 1095), Feofila, recluse (XII – XIII), Feofila and John (XII),'),
(date '2026-09-29','Venerable Kyriaka, pustelnyka (556). Martyr Dady, Haveddaia and Kazdoi (IV). Venerable Feofana Mylostyvoho.'),
(date '2026-09-30','Hieromartyr Hryhoriia, Bishop, enlightener Virmenii (ca. 335). Saint Mykhaila, pershoho Metropolitan of Kyiv and vsiiei Rusy (992). Martyr Rypsymii, Haianii and z nymy 35 Saints div (poch. IV). ZhOVTEN BohosluzhBovi vkazivky 2026 240'),
(date '2026-10-01','Protection of Our Most Holy Lady Theotokos and Ever-Virgin Mary. Apostle Ananias of the Seventy. Venerable Romanos the Melodist.'),
(date '2026-10-02','Hieromartyr Kypriana, Bishop, mts. Yustyny and mch. Feoktysta (304). Righteous Andriia Konstantynopolskoho, iurodyvoho zarady Khrysta (936). Martyr Davyda and Kostiantyna, kniaziv Arahvetskykh (740, Hruz.).'),
(date '2026-10-03','Hieromartyr Dionisiia Areopahita, Bishop Afinskoho, Rustyka, presbyter, and Yelevferiia, deacon (96). Venerable Dionisiia, recluse Kyievo-of the Caves, in the Far Caves (KhV). Venerable John Khozevita, Bishop Kesariiskoho (VI). Saint Isykhiia Khoryvita (VI).'),
(date '2026-10-04','18th Sunday after Pentecost. Tone 1. Hieromartyr Iierofeia, Bishop Afinskoho (I). Hieromartyr Haia, Favsta, Yevseviia and Kherymona, dyiakoniv (III). Hieromartyr Petra Kapitoliiskoho, presvit. (III – IV). Martyr Domniny and dochok her Virynei (Veroniky) and Proskudii (Prosdoky) (305 – 306). Venerable Amona Nitriiskoho (ca. 350). Venerable Pavla Preprostoho (IV). Martyr Davykta (Adavkta) and dochky his sv. Kalisfenii (IV). Right-believing kn. Volodymyr Yaroslavovycha, Novhorodskoho Wonderworker (1052). Venerable Elladiia and Onysyma, zatvornykiv of the Kyiv Caves, in the Near Caves (XII – XIII). Venerable Ammona, recluse Kyievo-of the Caves, in the Far Caves (XIII). Saint Stefana Shchylianovycha (1515, Serb.).'),
(date '2026-10-05','19th week after Pentecost. Martyr Kharytyny (304). Venerable Damiana, presvit., tsilytelia (1071), Yeremii (ca. 1070) and Matfeia (ca. 1085) prozorlyvykh, of the Kyiv Caves, in the Near Caves. Hieromartyr Dionisiia, Bishop Oleksandriiskoho (264 – 265). Martyr Mamelkhvy Perskoi (ca. 344). Venerable Hryhoriia Khandzoiskoho (861, Hruz.).'),
(date '2026-10-06','Apostola Fomy (I). Hieromartyr Nykyfora, arkhidyiak., ekzarkha Konstantynopolskoho patriarkha in Ukraini (1599).'),
(date '2026-10-07','Martyr Serhiia and Vakkha (290 – 303). Venerable Serhiia Poslushnoho, Kyievo-of the Caves, in the Near Caves (ca. XIII). Hieromartyr Yuliana, presbyter, and Kesariia, deacon (I). Martyr Pelahei, divy Tarsiiskoi (290). Hieromartyr Polikhroniia, presbyter (IV).'),
(date '2026-10-08','Venerable Pelahei Palestynskoi (457). Venerable Taisii Yehypetskoi (IV). Martyr Pelahii, divy Antiokhiiskoi (303).'),
(date '2026-10-09','Apostola Yakova Alfeievoho (I). Venerable Andronika and druzhyny his Afanasii (V). Righteous Avraama, praottsia, and pleminnyka his Lota (2000 do R. X.). Martyr Yeventiia (Yuventyna) and Maksyma, voiniv (361 – 363). Martyr Poplii (Publii), Confessor, deaconess Antiokhiiskoi (ca. 361 – 363). Venerable Petra Halatiiskoho (IX).'),
(date '2026-10-10','Martyr Yevlampiia and mts. Yevlampii ( IV). Saint Amphilochius Kyievo-of the Caves, Bishop Volodymyrskoho (1 122). Synaxis of Volynskykh Saints. Martyr Feotekna Antiokhiiskoho (III – IV). Venerable Vassiana Konstantynopolskoho, Abbot (V). Venerable Feofila, Confessor (VIII). Brailivskoi Icon of the Mother of God.'),
(date '2026-10-11','19th Sunday after Pentecost. Tone 2. Pam’iat Saints ottsiv VII Vselenskoho Synaxis ofu (787) (perekhidne sviatkuvannia in nediliu, naiblyzhchu do 1 1 zhovtnia). Apostle Fylypa, odnoho z 7-my dyiakoniv (I). Venerable Feofana, spovidnyka, tvortsia kanoniv, Bishop Nikeiskoho (ca. 850). Venerable Feofana, faster Kyievo-of the Caves, in the Near Caves (XII). Martyr Zinaidy and Filonily (I).'),
(date '2026-10-12','20th week after Pentecost. Martyr Prova, Tarakha and Andronika (304). Venerable Kosmy, Bishop Maiumskoho, tvortsia kanoniv (ca. 787). Martyr Domniky (286). Saint Martyna Mylostyvoho, Bishop Turskoho (ca. 400). Yerusalymskoi (48), Rudnenskoi (1687) Icon of the Mother of God.'),
(date '2026-10-13','Hieromartyr Karpa, Bishop Fiatyrskoho, Papyly, deacon, mch. Ahafodora and mts. Ahafoniky (ca. 251). Venerable Veniamina, recluse Kyievo-of the Caves, in the Far Caves (XIV). Martyr Florentiia Solunskoho (I – II). Hieromartyr Veniamina, deacon (421 – 424). Venerable Mykyty, Confessor (ca. 838). «Iversko-Myrnenskoi (Myrotochyvoi)» Icon of the Mother of God.'),
(date '2026-10-14','Vyshhorodskoi Icon of the Mother of God (I). Martyr Nazariia, Hervasiia, Protasiia, Kelsiia (I). Venerable Paraskevy Serbskoi (XI). Venerable Mykoly Sviatoshi, kn. Chernihivskoho, Kyievo-of the Caves Wonderworker, in the Near Caves (1 1 43). Hieromartyr Sylvana, presbyter Hazkoho (IV).'),
(date '2026-10-15','Venerable Yevfymiia Novoho, Solunskoho, iierodyiak. (898). Venerable Martyr Lukiana, presbyter Antiokhiiskoho (312). Hieromartyr Lukiana, Kyievo-of the Caves, in the Far Caves (1243). Martyr Sarvyla and mts. Vevei (II). Saint Savyna, Bishop Katanskoho (760). Icon of the Mother of God «Prymnozhennia khlibiv» (KhIKh).'),
(date '2026-10-16','Martyr Lonhyna, sotnyka, iakyi buv bilia Khresta Hospodnoho (I). Venerable Lonhyna, vorotaria Kyievo-of the Caves, in the Far Caves (XIII – XIV).'),
(date '2026-10-17','Prophet Osii (820 do R. X.). Venerable Martyr Andriia Krytskoho (767). Martyr, bezsrr. Kosmy and Damiana Araviiskykh and brativ ikhnikh mchch. Leontiia, Anfima and Yevtropiia (287 abo 303). Perenesennia moshchiv prav. Lazaria Chotyrydennoho, Bishop Kytiiskoho (898). ZhOVTEN BohosluzhBovi vkazivky 2026 250 Icon of the Mother of God, called «Do Rizdva and after Rizdva Diva» (1827) and «Vyzvolytelka» (bilia 1889).'),
(date '2026-10-18','20th Sunday after Pentecost. Tone 3. Apostola and ievanhelista Luky (I). Martyr Maryna Anazarvskoho (IV). Venerable Yuliana Perskoho (IV). Great Martyr Zlaty (Khrysy) Mehlenskoi (1795, Bolh.). Synaxis of Saints tsilyteliv (perekhidne sviatkuvannia u nediliu, naiblyzhchu do 1 7 – 18 zhovtnia).'),
(date '2026-10-19','21th week after Pentecost. Prophet Ioilia (800 do R. X.). Martyr Uara Yehypetskoho and z nym 7-okh uchyteliv khrystyianskykh (ca. 307). Saint Kleopatry (327) and her son of John (320). Hieromartyr Sadoka, Bishop Perskoho, and z nym 128 mchch. (342). Venerable Havryila Afonskoho (1901).'),
(date '2026-10-20','Great Martyr Artemiia (362).'),
(date '2026-10-21','Venerable Ilariona the Great (371 – 372). Martyr Dasiia, Haia and Zotyka (303). Saint Ilariona, Metropolitan of Kyiv (XI). Venerable Ilariona, skhymnyka Kyievo-of the Caves, in the Far Caves (XI). Perenesennia moshchiv svt. Ilariona, Bishop Mehlynskoho (1206).'),
(date '2026-10-22','Equal-to-the-Apostles Averkiia, Bishop Iierapolskoho, Wonderworker (ca. 167). Saint Rafaila (Zaborovskoho), Metropolitan of Kyiv, Halytskoho and vsiiei Rusy (1 747). Simokh otrokiv u Efesi: Maksymiliana, Yamvlykha, Martyniana, John, Dionisiia, Eksakustodiana (Kostiantyna) and Antonina (ca. 250; 408 – 450). Hieromartyr Oleksandra, Bishop Adrianopolskoho, mch. Irakliia, voina, and mtsts. Anny, Yelyzavety, Feodory and Hlikerii (II – III). Andronykivskoi (1281 – 1332) Icon of the Mother of God. P ravoslavna Ts erkva Ukrainy ZhOVTEN 253'),
(date '2026-10-23','Apostola z 70-kh Yakova, brother of of the Lord za plottiu (ca. 63). Saint Ihnatiia, patr. Konstantynopolskoho (877 – 878).'),
(date '2026-10-24','Dymytrivska pomynalna Saturday. Martyr Arefy and z nym 4299 mchch. (523). Venerable Arefy (ca. 1 195), Sysoia (XII – XIII) and Feofila (XII – XIII), zatvornykiv of the Kyiv Caves, in the Near Caves. Saint Elezvoia, zatv., tsaria Efiopskoho (ca. 553 – 555). Martyr Synklytikii and dvokh dochok her (VI). Saint Afanasiia, patr. Konstantynopolskoho (131 1). Icon of the Mother of God «Vsikh skorbotnykh radist» (1688).'),
(date '2026-10-25','21th Sunday after Pentecost. Tone 4. Martyr Markiana, chyttsia and Martyriia, ipodeacon (ca. 355). Venerable Martyriia, deacon, and Martyriia, recluse, of the Kyiv Caves, in the Far Caves (XIII – XIV). Martyr Anastasiia Akvileiskoho (III). Righteous Tavify Iopiiskoi (I).'),
(date '2026-10-26','22th week after Pentecost. Great Martyr Dymytriia Solunskoho (ca. 306). Venerable Feofila Kyievo-of the Caves, Bishop Novhorodskoho, in the Far Caves (ca. 1 482). Martyr Lupa Solunskoho (ca. 306). Venerable Afanasiia Mydikiiskoho (ca. 814). Venerable Dymytriia Basarbovskoho (1685, Bolh.). ZhOVTEN BohosluzhBovi vkazivky 2026 256'),
(date '2026-10-27','Martyr Nestora Solunskoho (ca. 306). Venerable Nestora Litopystsia, Kyievo-of the Caves, in the Near Caves (ca. 1 1 1 4). Venerable Nestora, neknyzhnoho, Kyievo-of the Caves, in the Far Caves (XIV). Martyr Kapitoliny and Yerotyidy (304). Martyr Marka Fivaidskoho and inshykh z nym.'),
(date '2026-10-28','Great Martyr Paraskevy-P’iatnytsi (III). Venerable Iova, Abbot of Pochaiv (1 651). Saint Dymytriia (Tuptala), Metropolitan Rostovskoho (1 709). Martyr Terentiia, mts. Neonily and ditei ikhnikh Sarvyla, Fota, Feodula, Iieraksa, Nyta, Vyla and Yevnykii (ca. 249 – 250). Venerable Stefana Savaita, tvortsia kanoniv (IX). Saint Arseniia, Archbishop Serbskoho (1266). Martyr Afrykana, Terentiia, Maksyma, Pompiia and inshykh 36-ty (III). Hieromartyr Kyriaka, patr. Yerusalymskoho (363). Venerable John Khozevita, Bishop Kesariiskoho (VI). Hieromartyr Neofita, Bishop Urbnyskoho (VII, Hruz.). Venerable Feofila of Kyiv, iurodyvoho zarady Khrysta (1853).'),
(date '2026-10-29','Venerable Martyr Anastasii Rymlianky (Solunskoi) (III). Venerable Avraamiia, recluse, presvit. and sv. Marii, pleminnytsi his (ca. 360). Martyr Klavdiia, Asteriia, Neona and Feonily (285). Venerable Anny (826).'),
(date '2026-10-30','Hieromartyr Zynoviia, Bishop Eheiskoho, and sister of his mts. Zynovii (285). Apostle vid 70-kh: Tertiia (Terentiia), Marka, Yusta (Varsavy) and Artemy (I). Hieromartyr Markiana, Bishop Syrakuzkoho (II). Martyr Yevtropii Oleksandriiskoi (ca. 250). Saint Stefana Myliutyna, korolia Serbskoho (1320), brother of his Drahutyna (1316) and materi their Oleny (1306, Serb.). Ozerianskoi Icon of the Mother of God (KhVI).'),
(date '2026-10-31','Apostle vid 70-kh: Stakhiia, Ampliia, Urvana, Narkysa, Apeliia and Arystovula (I). Martyr Epymakha (ca. 250). Venerable Spyrydona and Nykodyma, prosfornykiv of the Kyiv Caves, in the Near Caves (XII). Venerable Mavry Konstantynopolskoi, deaconess (V). Righteous Petra (Kalnyshevskoho) Bahatostrazhdalnoho (1803).'),
(date '2026-11-01','22th Sunday after Pentecost. Tone 5. Bezsrr. and chudotvortsiv Kosmy and Damiana Asiiskykh and materi their prp. Feodotii (III). Hieromartyr John, Bishop, and Yakova, presbyter, iaki in Persii postrazhdaly (ca. 345). Martyr Kiriieny and Yulianii (305 – 31 1). Martyr Ermynynhelda, tsarevycha Hotskoho (586). Martyr Kesariia, Dasiia and z nymy p’iatokh (VII).'),
(date '2026-11-02','23th week after Pentecost. Martyr Akyndyna, Pyhasiia, Afoniia, Elpidofora, Anempodysta and inshykh z nymy (ca. 341 – 345). Venerable Markiana Kyryneiskoho (388).'),
(date '2026-11-03','Hieromartyr Akepsyma, Bishop, Yosyfa, presvit., and Aifala, dyiak. (IV). Onovlennia khramu vmch. Yuriia (Heorhiia) in Liddi (IV). Martyr Atyka, Ahapiia, Yevdoksiia, Kateriia, Istukariia, Paktoviia, Nyktopoliona and voiniv ikh (ca. 320). Venerable Akepsyma Antiokhiiskoho (IV). Righteous Snandulii (IV). Venerable Anny Vsevolodivny, kniazhny Kyivskoi (1 1 12).'),
(date '2026-11-04','Venerable Ioanykiia the Great (846). Hieromartyr Nykandra, Bishop Myrskoho, and Yermiia, presvit. (I). Pam’iat osviachennia Synaxis ofu Saint Sofii in Kyievi (XI). Venerable Merkuriia, faster Kyievo-of the Caves, in the Far Caves (XIV). Saint Pavla (Koniushkevycha), Metropolitan Tobolskoho (1 770). Icon of the Mother of God «Oranta-Neporushna stina» (XI).'),
(date '2026-11-05','Martyr Halaktiona and mts. Yepistymii (III). Apostle vid 70-kh: Patrova, Yerma, Lina, Haia, Filoloha (I). Saint Hryhoriia, Archbishop Oleksandriiskoho (IX).'),
(date '2026-11-06','Hieromartyr Pavla, Archbishop Konstantynopolskoho, Confessor (350). Venerable Luky, Iconoma Kyievo-of the Caves, in the Near Caves (XIII). Martyr Tekusy, Oleksandry, Polaktii, Klavdii, Yevfrasii, Afanasii and Motrony (III). Venerable Luky Tavromeniiskoho (800 – 820).'),
(date '2026-11-07','Martyr postrazhdalykh u Melytyni: Iierona, Isykhiia, Nykandra, Afanasiia, Mamanta, Varakhiia, Kalynyka, Feohena, Nykona, Lonhyna, Fedora, Valeriia, Ksanfa, Feodula, Kalymakha, Yevheniia, Feodokha, Ostrykhiia, Epifaniia, Maksymiana, Dukytiia, Klavdiana, Feofila, Hihantiia, Dorofeia, Feodota, Kastrykiia, Anykyty, Femeliia, Yevtykhiia, Ilariona, Diodota and Amonyta (III). Venerable Lazaria Halisiiskoho, iierom. (1053). Martyr Feodota Ankyrskoho, korchmar (303). Martyr Melasypa and Kasynii and son of ikhnoho Antonina (363). Martyr Avkta, Tavriona and Fesalonikii.'),
(date '2026-11-08','23th Sunday after Pentecost. Tone 6. Synaxis of arkhistratyha Mykhaila and inshykh nebesnykh syl bezplotnykh. Arkhanheliv: Havryila, Rafaila, Uryila, Selafyila, Iiehudyila, Varakhyila and Iieremyila.'),
(date '2026-11-09','24th week after Pentecost. Martyr Onysyfora and Porfyriia (ca. 284 – 305). Venerable Motrony Konstantynopolskoi (ca. 492). Venerable Feoktysty (881). Venerable Onysyfora, spovidnyka Kyievo-of the Caves, in the Near Caves (1 1 48). Martyr Oleksandra Solunskoho (IV). Martyr Anthony Apameiskoho (V). Venerable John Kolova (V). Venerable Yevstolii (610) and Sosypatry (625). Saint Nektariia Ehinskoho, Metropolitan Pentapolskoho, Wonderworker (1920). Icon of the Mother of God «Skoroposlushnytsia» (X).'),
(date '2026-11-10','Apostle vid 70-kh: Erasta, Olimpa, Rodiona, Sosypatra, Kuarta (Kvarta) and Tertiia (Terentiia) (I). Martyr Oresta Tianskoho, likaria (304). Hieromartyr Myliia, Bishop Perskoho, and dvokh uchniv his (341). Venerable Feostyrykta, shcho in Symvolakh. Martyr Kostiantyna, kn. Hruzynskoho (842). Kolesuvannia vmch. Heorhiia (303, Hruz.). P ravoslavna Ts erkva Ukrainy LYSTOPAD 265'),
(date '2026-11-11','Great Martyr Myny Fryhiiskoho, voina (304). Martyr Viktora and mts. Stefanydy (II). Hieromartyr Vikentiia Sarahoskoho, dyiak. (304). Venerable Fedora Studyta, Confessor (826). Martyr Stefana Dechanskoho (ca. 1336, Serb.).'),
(date '2026-11-12','Saint John Mylostyvoho, patr. Oleksandriiskoho (620). Venerable Nila, faster (V). Prophet Akhii (960 do R. X.). Icon of the Mother of God «Mylostyva».'),
(date '2026-11-13','Saint John Zolotoustoho, Archbishop Konstantynopolskoho (407). Hieromartyr Antonina, presbyter, mchch. Nykyfora and Hermana (308). Martyr Manefy (308).'),
(date '2026-11-14','Apostola Fylypa (I). Saint blhv. Vizantiiskoho imperatora Yustyniana (565) and imperatrytsi Feodory (548). Saint Hryhoriia Palamy, Archbishop Fessalonikiiskoho (ca. 1360).'),
(date '2026-11-15','24th Sunday after Pentecost. Tone 7. Martyr and spovv. Huriia, Samona (299 – 306) and sshchmch. Aviva, dyiak. (322). Venerable Paisiia Velychkovskoho (1 794). Martyr Elpidiia, Markela and Yevstokhiia (361 – 363). Martyr Dymytriia (ca. 307). Kup’iatytskoi Icon of the Mother of God (1 182).'),
(date '2026-11-16','25th week after Pentecost. Apostola and ievanhelista Matfeia (60). Righteous Fulviana, kn. Efiopskoho, u sv. khreshchenni Matfeia (I).'),
(date '2026-11-17','Saint Hryhoriia Wonderworker, Bishop Neokesariiskoho (ca. 266 – 270). Venerable Lazaria, Iconopystsia (ca. 857). Martyr Hob- rona, u sv. khreshchenni Mykhaila, and z nym 133 voiniv (914, Hruz.). Martyr Atsiskla and Viktorii Korduviiskykh (Kordubskykh) (IV).'),
(date '2026-11-18','Martyr Platona Ankyrskoho (302 abo 306). Hieromartyr Romana, deacon, and mch. otroka Varula (303). Hieromartyr Zakkheia, dyiak. Hadarynskoho, and mch. Alfeia, chyttsia Kesariiskoho (303).'),
(date '2026-11-19','Prophet Avdiia, z 12-okh (IX century BC). Martyr Varlaama (ca. 304). Venerable Varlaama, pustelnyka and Ioasafa, tsarevycha Indiiskoho, and batka his Avenira, tsaria (IV). Venerable Varlaama, Abbot Kyievo-of the Caves, in the Near Caves (1065). Martyr Azy and z nym 150 voiniv (284 – 305). Martyr Iliodora Pamfiliiskoho (ca. 273). Venerable Ilariona, Wonderworker (875, Hruz.). Icon of the Mother of God «V skorbotakh and pechaliakh utikha» (1863).'),
(date '2026-11-20','Forefeast Vvedennia in khram the Most Holy Theotokos. Venerable Hryhoriia Dekapolita (ca. 842). Saint Prokla, Archbishop Konstantynopolskoho (446 – 447). Martyr Dasiia Dorostolskoho (284 – 305). Martyr Yevstafiia, Fespesiia and Anatoliia (312). Hieromartyr Nyrsy, Bishop, and Yosyfa, uchnia his, John, Saveriia, Isakiia and Ipatiia, iepp. Perskykh; mchch. Azata, skoptsia, Sasoniia, Fekly, Anny and inshykh bahatokh cholovikiv and zhinok, iaki in Persii postrazhdaly (343). P ravoslavna Ts erkva Ukrainy LYSTOPAD 271'),
(date '2026-11-21','Entrance of Our Most Holy Lady Theotokos and Ever-Virgin Mary into the Temple.'),
(date '2026-11-22','25th Sunday after Pentecost. Tone 8. Afterfeast Vvedennia. Apostle vid 70-kh: Fylymona and Arkhypa and mts. rivnoap. Apfii (I). Right-believing Yaropolka, u sv. khreshchenni Petra, kn. Volodymyrskoho (1086). Martyr Kykylii (Tsetsylii), mchch. Valeriana, Tyvurtiia and Maksyma (ca. 230). Martyr Prokopiia Kesariiskoho, chyttsia (303). Martyr Menyhna (250). Venerable Ahavy Izrailtianyna (V). Righteous Mykhaila, voina, bolharyna (866).'),
(date '2026-11-23','26th week after Pentecost. Saint Amphilochius, Bishop Iconiiskoho (after 394). Saint Hryhoriia, Bishop Akrahantiiskoho (VI – VII). Hieromartyr Sysyniia, Bishop Kyzytskoho (III), and mch. Fedora Antiokhiiskoho (IV). Venerable Oleksandra, founder of obyteli «Nevsypushchykh» (ca. 430).'),
(date '2026-11-24','Great Martyr Merkuriia (III). Great Martyr Kateryny (305 – 313). Venerable Merkuriia, faster Kyievo-of the Caves, in the Far Caves (XIV). Martyr Avhusty Rymskoi, mchch. Porfyriia Stratylata and 200 voiniv (305 – 313). Venerable Mastrydii Oleksandriiskoi. Venerable Merkuriia Chernihivskoho, Abbot Bryhynskoho (1956).'),
(date '2026-11-25','Leavetaking of the Feast of Vvedennia in khram the Most Holy Theotokos. Hieromartyr Klymenta, iepyskopa Rymskoho (101), and Petra, Archbishop Oleksandriiskoho (31 1). Venerable Petra Halatiiskoho, movchalnyka (ca. 429).'),
(date '2026-11-26','Venerable Alipiia stylite (640). Venerable Styliana Paflahonskoho ( V-VI st.) Saint Inokentiia (Kulchytskoho), Bishop Irkutskoho (1 731). Venerable Yakova Syriiskoho, pustelnyka (457). Osviachennia khramu sv. vmch. Yuriia Peremozhtsia, shcho in Kyievi bilia Zolotykh vorit (XI).'),
(date '2026-11-27','Great Martyr Yakova Perskoho (421). Venerable Palladiia Oleksandriiskoho (VI – VII). Venerable Martyr 17 monakhiv in Indii (IV). Venerable Romana Antiokhiiskoho (V). Znaidennia moshchiv blhv. Vsevoloda, u sv. khreshchenni Havryila, kn. Novhorodskoho, Wonderworker (1 192). Icon of the Mother of God «Znamennia».'),
(date '2026-11-28','Pomynalna Saturday vsikh, in Ukraini holodom zamorenykh. Venerable Martyr and Confessor Stefana Novoho (767). Martyr Irynarkha Sevastiiskoho and Saints simokh zhinok (303). Martyr Stefana, Vasyliia, Hryhoriia, inshoho Hryhoriia, John and bahatokh in. (VIII).'),
(date '2026-11-29','26th Sunday after Pentecost. Tone 1. Martyr Paramona and z nym 370 mchch. (250). Martyr Filumena Ankyrskoho (ca. 274). Venerable Akakiia Synaiskoho (VI). Venerable Nektariia Kyievo-of the Caves, in the Near Caves (XII). Hieromartyr Aviva, Bishop Nekreskoho (VI, Hruz.).'),
(date '2026-11-30','27th week after Pentecost. Apostola Andriia Pershozvanoho (62). Saint Frumentiia, Archbishop Indiiskoho (Efiopskoho, ca. 380).'),
(date '2026-12-01','Prophet Nauma (VII century BC). Righteous Filareta Mylostyvoho (792). Martyr Ananii Perskoho.'),
(date '2026-12-02','Prophet Avakuma (VII century BC). Venerable Afanasiia, recluse Kyievo-of the Caves, in the Near Caves (ca. 1 1 76), and inshoho Afanasiia, recluse Kyievo-of the Caves, in the Far Caves (XIII). Martyr Myropii Khioskoi (ca. 251). Venerable John, Iraklemona, Andriia and Feofila (IV). Saint Ise (Iieseia), Bishop Tsylkanskoho (VI, Hruz.). Saint Stefana Urosha, tsaria Serbskoho (1367). Hieromartyr Porfyriia, Bishop Simferopolskoho (1937). Venerable Oleksiia Karpatoruskoho (1947). Venerable Porfyriia Kavsokalivita (1991). Icon of the Mother of God «Herondysa».'),
(date '2026-12-03','Prophet Sofonii (635 – 605 do R. X.). Venerable Feodula Konstantynopolskoho (ca. 440). Venerable John Movchalnyka, kolyshnoho Bishop Koloniiskoho (558). Hieromartyr Fedora, Archbishop Oleksandriiskoho (606).'),
(date '2026-12-04','Great Martyr Varvary and mts. Yulianii (ca. 306). Venerable John Damaskyna (ca. 780). Venerable John, Bishop Polivotskoho, Confessor (VIII).'),
(date '2026-12-05','Venerable Savy Osviachenoho (532). Martyr Anastasiia Akvileiskoho. Venerable Kyriona, chentsia, and son of his Zakharii, iehyptian (IV).'),
(date '2026-12-06','Saint Nicholas, Archbishop of Myra in Lycia, Wonderworker.'),
(date '2026-12-07','28th week after Pentecost. Saint Amvrosiia, Bishop Mediolanskoho (397). Venerable John, faster Kyievo-of the Caves, in the Near Caves (XII). Martyr Afinodora Mesopotamskoho (ca. 304). Venerable Pavla Poslushnoho. Martyr Filofei (1060, Rumun.).'),
(date '2026-12-08','Venerable Patapiia Fivskoho (VII). Apostle vid 70-kh: Sosfena, Apolosa, Kyfy, Tykhyka, Epafrodyta, Kesariia and Onysy- fora (I). Hieromartyr 62 iiereiv and mchch. 300 myrian, iaki in Afrytsi vid arian postrazhdaly (477). Martyr Anfisy Rymskoi (V).'),
(date '2026-12-09','Zachattia prav. Annoiu the Most Holy Theotokos. Prorochytsi Anny, materi pror. Samuila (1 100 do R. X.). Saint Sofroniia, Archbishop Kiprskoho (VI). Venerable Stefana Novosiaiuchoho (912). Icon of the Mother of God «Nespodivana radist».'),
(date '2026-12-10','Martyr Myny, Yermohena and Yevhrafa Oleksandriiskykh (ca. 313). Saint Ioasafa (Horlenka), Bishop Bilhorodskoho (1 754). Martyr Hemela Paflahonskoho (ca. 361). Venerable Fomy, Abbot (X). Saint blhvv. John (1503) and batkiv his, Stefana (1446) and prp. Anheliny, pravyteliv Serbskykh.'),
(date '2026-12-11','Venerable Danyila stylite (489 – 490). Venerable Nykona Sukhoho, Kyievo-of the Caves, in the Near Caves (XII). Martyr Myraksa Yehypetskoho (VII). Martyr Akepsiia and Aifala. Venerable Luky stylite, iierom. (ca. 970 – 980).'),
(date '2026-12-12','Saint Spyrydona, Bishop Trymyfuntskoho, Wonderworker (ca. 348). Hieromartyr Oleksandra, Bishop Yerusalymskoho (251). Martyr Rozumnyka (Syneziia) (270 – 275).'),
(date '2026-12-13','28th Sunday after Pentecost, Saints praottsiv. Tone 3. Martyr Yevstratiia, Avksentiia, Yevheniia, Mardariia and Oresta (284 – 305). Martyr Lukii Sirakuzkoi (304). Venerable Arkadiia Novotorzkoho (XI). Venerable Mardariia, recluse Kyievo-of the Caves, in the Far Caves (XIII). Venerable Arseniia Latriiskoho, Abbot (VIII – X). Saint Dosyfeia, Metropolitan Moldovskoho (1693, Rum.).'),
(date '2026-12-14','29th week after Pentecost. Martyr Firsa, Levkiia and Kalynyka (249 – 251). Martyr Fylymona, Apoloniia, Ariana and Feotykha (286 – 287).'),
(date '2026-12-15','Hieromartyr Yelevferiia, Bishop, materi his mts. Anfii and mch. Koryva, ieparkha (II). Venerable Pavla Latriiskoho (955). Saint Stefana, Confessor, Archbishop Surozkoho (VIII). Synaxis of Krymskykh Saints. Martyr Yelevferiia Vizantiiskoho (305 – 31 1). Venerable Parda, samitnyka (VI).'),
(date '2026-12-16','Prophet Aheia (500 do R. X.). Martyr Maryna Rymskoho (III). Saint blhv. imperatrytsi Vizantiiskoi Feofanii (893 – 894).'),
(date '2026-12-17','Prophet Danyila and trokh otrokiv: Ananii, Azarii and Mysaila (600 do R. X.). Venerable Danyila Yehypetskoho, Confessor, u skhymi Stefana (X).'),
(date '2026-12-18','Martyr Sevastiana Mediolanskoho and voiniv his: Nykostrata skarbnyka, druzhyny his Zoi, Kastoriia, sshchmchch. Trankvyllina, presbyter, and syniv his Markelina and Marka, dyiakoniv, mchch. Klavdiia, nachalnyka in’iaznyts, son of his Symforiana, brother of his Viktoryna, Tyvurtiia and Kastula (ca. 287). Saint Modesta, Archbishop Yerusalymskoho (633 – 634). Venerable Flora, Bishop Amiiskoho (VII). Venerable Mykhaila Synkela, spovidnyka (ca. 845).'),
(date '2026-12-19','Saturday before Rizdvom Khrystovym. Martyr Vonifatiia (290). Venerable Illi Muromtsia, Kyievo-of the Caves, in the Near Caves (ca. 1 188). Martyr Illi, Prova and Arysa, iehyptian (308). Martyr Poliievkta and sshchmch. Tymofiia, deacon (IV). Saint Vonifatiia Mylostyvoho, Bishop Ferentiiskoho (VI). Saint Hryhoriia, Bishop Omyrytskoho (ca. 552).'),
(date '2026-12-20','29th Sunday after Pentecost, before Rizdvom Khrystovym, Saints ottsiv. Tone 4. Forefeast Rizdva Khrystovoho. Hieromartyr Ihnatiia Bohonostsia, Bishop (107). Venerable Ihnatiia, arkhim. Kyievo-Pechers- koho, in the Far Caves (1 435). Saint Filohoniia, Bishop Antiokhiiskoho (323). Saint Danyila, Archbishop Serbskoho (1338). Novodvirtsivskoi and Lenkivskoi (Novhorod-Siverskoi), zvanoi «Spasytelka potopaiuchykh», Icon of the Mother of God.'),
(date '2026-12-21','30th week after Pentecost. Martyr Yulianii and z neiu mchch. 500 cholovikiv and mtsts. 130 zhinok, shcho in Nikomydii postrazhdaly (304). Saint Petra, Metropolitan of Kyiv and vsiiei Rusy Wonderworker (1326). Martyr Femistokleia Myrlikiiskoho (251). Saint Filareta, Metropolitan of Kyiv and Halytskoho (1857).'),
(date '2026-12-22','Great Martyr Anastasii Uzorishytelnytsi (ca. 304). Martyr Khrysohona, Feodotii, Yevoda, Yevtykhiana and inshykh (ca. 304). HRU DEN BohosluzhBovi vkazivky 2026 290'),
(date '2026-12-23','Martyr na Kryti: Feodula, Satornyna, Evpora, Helasiia, Evnykiana, Zotyka, Pompiia, Ahafopusa, Vasylida and Evaresta (III). Venerable Nyfonta, Bishop Kiprskoho (IV). Venerable Pavla, Bishop Neokesariiskoho (IV).'),
(date '2026-12-24','Eve of Rizdva Khrystovoho (Rizdvianyi Eve). Prmts. Yevhenii and z neiu mchch. Prota, Yakynfa and mts. Klavdii (ca. 262). Venerable Nicholas, chentsia (IX). Venerable Kukshi Odeskoho (1964).'),
(date '2026-12-25','Nativity of Our Lord, God and Savior Jesus Christ.'),
(date '2026-12-26','Saturday after Rizdva Khrystovoho. Afterfeast Rizdva Khrystovoho. Synaxis of PreSaint Bohorodytsi. Hieromartyr Yevfymiia, Bishop Sardiiskoho (ca. 840). Venerable Kostiantyna Synadskoho (VIII). Venerable Evaresta Studyta (825). Vilensko-Ostrobramskykh, nazvanykh «Trokh radostei» and «Mylostyva» Icon of the Mother of God.'),
(date '2026-12-27','30th Sunday after Pentecost, after Rizdva Khrystovoho. Tone 5. Righteous Yosyfa Obruchnyka, Davyda, tsaria, and Yakova, brother of of the Lord. (perekhidne sviatkuvannia u nediliu'),
(date '2026-12-28','31th week after Pentecost. Martyr 20 000, shcho in Nikomydii buly spaleni: sshchmch. Hlykeriia, presvit., mch. Zynona, sshchmch. Feofila, dyiak., mchch. Dorofeia, Mardoniia, sshchmch. Myhdoniia, dyiak., mchch. Indysa, Horhoniia, Petra, Yevfymiia, mtsts. Ahafii, Domny, Feofily and inshykh (302). Apostle vid 70-kh Nykanora (34).'),
(date '2026-12-29','Venerable Iova Maniavskoho (1 621). Martyr 14 000 nemovliat, iakykh Irod ubyv u Vyfleiemi (I). Venerable Markela, ihumena obyteli «Nevsypushchykh» (485). Venerable Marka, hrobokopacha, Feofila and John of the Kyiv Caves, in the Near Caves (XII). Venerable Fadeia Studyta, Confessor (818). P ravoslavna Ts erkva Ukrainy HRU DEN 297'),
(date '2026-12-30','Martyr Anisii Solunskoi (285 – 305). Hieromartyr Zotyka, presbyter (IV). Apostle vid 70-kh Tymona, Bishop Bostriiskoho (I). Martyr Filetera Nikomydiiskoho (31 1). Venerable Feodory Kesariiskoi (VIII). Venerable Feodory Konstantynopolskoi (940).'),
(date '2026-12-31','Leavetaking of the Nativity of Christ. Venerable Melania of Rome. Saint Peter Mohyla, Metropolitan of Kyiv, Galicia, and All Rus’.')
)
insert into public.calendar_day_translations (
  calendar_day_id, language_code, title, saints, details, fasting_note
)
select d.id, 'en', p.title, d.saints, d.details, d.fasting_note
from payload p
join public.calendar_days d
  on d.country_code = 'UA'
 and d.calendar_code = 'ua-orthodox-church-of-ukraine'
 and d.language_code = 'uk'
 and d.calendar_date = p.calendar_date
on conflict (calendar_day_id, language_code) do update set
  title = excluded.title,
  saints = excluded.saints,
  details = excluded.details,
  fasting_note = excluded.fasting_note,
  updated_at = timezone('utc', now());

do $$
declare
  translation_count integer;
begin
  select count(*)
    into translation_count
  from public.calendar_days d
  join public.calendar_day_translations t on t.calendar_day_id = d.id
  where d.country_code = 'UA'
    and d.calendar_code = 'ua-orthodox-church-of-ukraine'
    and d.language_code = 'uk'
    and d.calendar_date between date '2026-01-01' and date '2026-12-31'
    and t.language_code = 'en';

  if translation_count <> 365 then
    raise exception 'Expected 365 UA English translations; found %', translation_count;
  end if;
end
$$;

commit;
